insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('power-outage-evening-calm-plan-sheet', 'Power Outage Evening Calm Plan Sheet', 'worksheet'::resource_kind, 'A one-page plan for the evening the power goes out: light, warmth, phone battery, who to check on and what to do with the dark hours.', 'Use it to help a client turn a sudden outage from a panic trigger into a rehearsed evening with a short list to follow.', array['Adults']::text[], '15 minutes, kept with the flashlight', 'Clients who live alone, or who feel unsafe in the dark, often describe an outage as the moment the whole evening unravels. The sheet asks where the flashlight and candles live, how the phone stays charged, which neighbor or relative gets a text, what the first warm meal that needs no stove is, and three things to do by lamplight that are not scrolling the outage map. Fill it in session while nothing is wrong, and keep a paper copy where it can be found without light. Watch for a client whose plan is entirely about catastrophe and has no comfort in it; add one.', '[{"id": "f0", "type": "textarea", "label": "Where my flashlight, candles and matches live, and the last time I checked them:"}, {"id": "f1", "type": "textarea", "label": "How my phone stays charged, and the one person I text to say the power is out:"}, {"id": "f2", "type": "textarea", "label": "A warm meal or drink I can make with no electricity:"}, {"id": "f3", "type": "textarea", "label": "Three things I can do by lamplight that are not checking the outage map:"}, {"id": "f4", "type": "textarea", "label": "What I tell myself if the dark starts to feel unsafe:"}, {"id": "f5", "type": "textarea", "label": "Who I call if it runs past bedtime and I do not want to be alone with it:"}]'::jsonb, array['stress', 'planning', 'safety']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('jury-duty-summons-week-logistics-sheet', 'Jury Duty Summons Week Logistics Sheet', 'worksheet'::resource_kind, 'A sheet for the week a jury summons lands, separating the logistics that need a call from the worries that need nothing yet.', 'Use it to help a client who is spiraling about a summons sort the practical tasks from the dread and finish the tasks first.', array['Adults']::text[], '20 minutes the day the summons arrives', 'A summons combines two things clients find hard at once: an unfamiliar official process and a loss of control over their week. The sheet asks what the paper actually says, the one phone number or website that answers questions, what has to be arranged for work, childcare and travel, and which worries are about the courthouse itself rather than the logistics. The courthouse worries go in their own box to bring to session. Watch for a client who treats a summons as a verdict on them; the sheet keeps it as paperwork with a date on it.', '[{"id": "f0", "type": "textarea", "label": "What the summons actually says: the date, the place and the time I need to arrive:"}, {"id": "f1", "type": "textarea", "label": "The one number or website I can call with questions, and when I will call it:"}, {"id": "f2", "type": "textarea", "label": "What I need to arrange for work, childcare, pets or travel, and who I need to tell:"}, {"id": "f3", "type": "textarea", "label": "Worries that are about the courthouse itself, not the logistics, for session:"}, {"id": "f4", "type": "textarea", "label": "What I will pack for a long day of waiting:"}, {"id": "f5", "type": "textarea", "label": "How I will spend the evening before so I arrive rested rather than wired:"}]'::jsonb, array['stress', 'planning', 'uncertainty']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('moving-boxes-last-ten-percent-finish-sheet', 'Moving Boxes Last Ten Percent Finish Sheet', 'worksheet'::resource_kind, 'A sheet for boxes still sealed months after a move, sorted into open now, open with help, donate unopened or keep sealed on purpose.', 'Use it to help a client finish the last stretch of a move that has stalled and stopped feeling like home.', array['Adults', 'Teens']::text[], 'One weekend, 30 minutes to plan', 'The last boxes of a move often hold the things with the most feeling in them, which is why they stay sealed. The sheet has the client count the boxes, label each from the outside without opening it, and sort them: open alone this weekend, open with someone there, donate without opening, or keep sealed on purpose for a date they name. A box kept sealed on purpose is a decision, not avoidance, as long as the date is written down. Review in session what each unopened box seems to be holding. Watch for shame about how long it has taken; the sheet starts from today.', '[{"id": "f0", "type": "textarea", "label": "How many boxes are still sealed, and where they are sitting:"}, {"id": "f1", "type": "textarea", "label": "Boxes I can open alone this weekend, by their labels:"}, {"id": "f2", "type": "textarea", "label": "Boxes I would rather open with someone in the room, and who that is:"}, {"id": "f3", "type": "textarea", "label": "Boxes I can donate or recycle without opening, and what I would be giving up by opening them anyway:"}, {"id": "f4", "type": "textarea", "label": "Boxes I am choosing to keep sealed, and the date I will come back to them:"}, {"id": "f5", "type": "textarea", "label": "What this place would need to feel like home once the boxes are gone:"}]'::jsonb, array['transitions', 'avoidance', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('overdue-dentist-appointment-booking-steps-sheet', 'Overdue Dentist Appointment Booking Steps Sheet', 'worksheet'::resource_kind, 'A step sheet for the dental appointment a client has put off for years, from finding the number to the first call.', 'Use it to help a client break a years-long avoidance of the dentist into one phone call and a plan for the chair.', array['Adults', 'Teens']::text[], '20 minutes, then one phone call', 'The longer a dental visit is postponed, the more it carries: shame about the gap, fear of what will be found, fear of being scolded, and the memory of pain. The sheet separates those into boxes, then lays out steps that end with a booked appointment rather than a finished course of care. The client writes the exact words for the call, including that it has been a while, and what they want the office to know about nerves before anything happens in the chair. Watch for a client who plans the perfect appointment and never dials; the only step that matters this week is the call.', '[{"id": "f0", "type": "textarea", "label": "How long it has been, and what I am most afraid of hearing when I go:"}, {"id": "f1", "type": "textarea", "label": "The office I will call, the number, and the day and time I will call:"}, {"id": "f2", "type": "textarea", "label": "What I will say, word for word, including that it has been a while:"}, {"id": "f3", "type": "textarea", "label": "What I want them to know about my nerves before I sit in the chair:"}, {"id": "f4", "type": "textarea", "label": "A reward for making the call, whatever the office says:"}, {"id": "f5", "type": "textarea", "label": "If I do not make the call, what got in the way, for session:"}]'::jsonb, array['avoidance', 'self-care', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('lost-wallet-first-hour-checklist-sheet', 'Lost Wallet First Hour Checklist Sheet', 'worksheet'::resource_kind, 'A checklist for the hour after a wallet goes missing: retrace, freeze, replace and breathe, in an order that outruns the panic.', 'Use it to give a client who freezes in a small emergency a sequence to follow so the hour ends with calls made instead of a spiral.', array['Adults', 'Teens']::text[], 'Fill in ahead; use in the hour it happens', 'Losing a wallet is a small emergency that reliably produces big-emergency feelings. The sheet is filled in before anything is lost: which cards are in the wallet and the numbers to freeze them, where the ID and spare key copies live, who to call for a ride or cash, and the three places to retrace before anything is canceled. In the hour itself the client follows the list from the top. Review afterward what the dread said would happen versus what did. Watch for a client who will not fill it in because planning for loss feels like inviting it.', '[{"id": "f0", "type": "textarea", "label": "What is in my wallet right now: cards, ID, cash, anything irreplaceable:"}, {"id": "f1", "type": "textarea", "label": "The numbers I would call to freeze each card, written here so I do not have to search:"}, {"id": "f2", "type": "textarea", "label": "The three places I would retrace first, before freezing anything:"}, {"id": "f3", "type": "textarea", "label": "Who I can call for a ride, a loan or a spare key, and where the spare documents live:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself in the first ten minutes, before I know anything:"}, {"id": "f5", "type": "textarea", "label": "After it is over: what the dread predicted, and what happened:"}]'::jsonb, array['stress', 'problem solving', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('left-on-read-for-two-days-thought-record', 'Left on Read for Two Days Thought Record', 'cbt'::resource_kind, 'A thought record for the message that has shown as read for two days with no reply, catching the story the silence tells.', 'Use it to help a client separate what a read receipt shows from what they have decided it means.', array['Adults', 'Teens']::text[], '15 minutes when the silence starts to sting', 'A read receipt with no reply is a blank the mind fills fast. The record walks the standard columns: the situation in one line, the automatic thought, the emotion and its strength, the evidence for and against, and a more balanced thought. The evidence column is where the work happens; most clients find the only hard fact is that the message was opened. Have them list five reasons a reply might be slow that have nothing to do with them. Watch for the client who sends a second message to end the uncertainty; name that as the urge it is.', '[{"id": "f0", "type": "textarea", "label": "Who I messaged, what I said, and how long it has shown as read:"}, {"id": "f1", "type": "textarea", "label": "The thought that arrives when I see the read receipt:"}, {"id": "f2", "type": "textarea", "label": "What I feel, and how strong it is from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Evidence that supports the thought, only facts I could show someone:"}, {"id": "f4", "type": "textarea", "label": "Five reasons a reply might be slow that have nothing to do with me:"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought, and how strong the feeling is now:"}]'::jsonb, array['thought record', 'automatic thoughts', 'relationships']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('wear-the-bright-jacket-attention-experiment-sheet', 'Wear the Bright Jacket Attention Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment that predicts how many people will notice and comment on a loud jacket, then counts what actually happens.', 'Use it to test a client''s belief that they are being watched and judged by strangers, with a prediction they can check.', array['Adults', 'Teens']::text[], 'One outing, 15 minutes to set up and review', 'Clients who believe they are constantly observed rarely test it. The experiment has them wear something they would never wear, a bright jacket or a loud hat, for one ordinary errand. Before leaving they predict how many people will look, how many will comment and what they will say, and rate their confidence. During the errand they count. Afterward they compare, and write what the result suggests about the spotlight they feel. Keep the item harmless and the errand short. Watch for a client who counts every glance as a judgment; glances and comments are separate tallies.', '[{"id": "f0", "type": "textarea", "label": "What I will wear, and the errand I will wear it on:"}, {"id": "f1", "type": "textarea", "label": "My prediction: how many people will look, how many will comment, and what they will say:"}, {"id": "f2", "type": "textarea", "label": "How sure I am, from 0 to 100, that people will notice and judge:"}, {"id": "f3", "type": "textarea", "label": "Tally during the errand: looks, comments, anything else:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, in plain description:"}, {"id": "f5", "type": "textarea", "label": "What this suggests about how closely strangers watch me, and how sure I am now:"}]'::jsonb, array['behavioral experiment', 'predictions', 'attention']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('coworker-sighed-during-my-update-thought-record', 'Coworker Sighed During My Update Thought Record', 'cbt'::resource_kind, 'A thought record for the sigh, eye rub or glance at the clock during a meeting that a client reads as a verdict on them.', 'Use it to catch mind reading in a small workplace moment and build a habit of checking other explanations.', array['Adults']::text[], '10 minutes after the meeting', 'A sigh in a meeting lands as a review. The record asks for the exact observable behavior, the interpretation the client attached, the feeling and its strength, and then the alternative explanations: the sigh could be about the room, the time, the last meeting, their own inbox. The client rates how likely each alternative is before rerating the original. Over a few weeks a pattern emerges of which coworkers and which gestures hook them most. Watch for a client who checks by asking the coworker what the sigh meant; that is reassurance seeking, not evidence gathering.', '[{"id": "f0", "type": "textarea", "label": "What I actually saw or heard, described so a camera would agree:"}, {"id": "f1", "type": "textarea", "label": "What I decided it meant about me:"}, {"id": "f2", "type": "textarea", "label": "What I felt, and how strong it was from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Four other things the sigh or glance could have been about:"}, {"id": "f4", "type": "textarea", "label": "How likely each explanation is, including mine, out of 100:"}, {"id": "f5", "type": "textarea", "label": "My rerated belief in the original thought, and how I feel now:"}]'::jsonb, array['thought record', 'thinking traps', 'automatic thoughts']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('whole-day-hinges-on-one-meeting-fortune-telling-sheet', 'Whole Day Hinges on One Meeting Fortune Telling Sheet', 'cbt'::resource_kind, 'A sheet for the morning a client has decided the whole day depends on one event, logging the prediction and the rest of the day as it goes.', 'Use it to help a client see how fortune telling about one event colors a day, and to test it against the hours that follow.', array['Adults', 'Teens']::text[], 'One day, two minutes at a time', 'Some mornings arrive with a verdict already written: if the meeting goes badly, the day is ruined. The sheet captures that prediction before the event, with a confidence rating, then has the client log the day in three-hour blocks, rating each block on its own rather than through the morning''s lens. In the evening they compare the prediction with the blocks. Most days contain a bad hour and several ordinary ones. Watch for a client who rates every block low to prove the morning right; ask for one specific thing that happened in each block.', '[{"id": "f0", "type": "textarea", "label": "The event today that my whole day seems to depend on, and what I am predicting:"}, {"id": "f1", "type": "textarea", "label": "How sure I am, from 0 to 100, that the day is decided by it:"}, {"id": "f2", "type": "textarea", "label": "How the event actually went, in two sentences:"}, {"id": "f3", "type": "textarea", "label": "The rest of the day in blocks, each rated on its own: morning, afternoon, evening:"}, {"id": "f4", "type": "textarea", "label": "One specific thing that happened in each block, good or neutral:"}, {"id": "f5", "type": "textarea", "label": "Looking back: how much of the day did the one event actually decide?"}]'::jsonb, array['thinking traps', 'predictions', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('downward-arrow-from-a-late-fee-sheet', 'Downward Arrow From a Late Fee Sheet', 'cbt'::resource_kind, 'A downward arrow that starts from a small, specific slip, a late fee, and follows the if-that-were-true chain to the belief underneath.', 'Use it to show a client how a minor financial slip connects to a core belief, using the same chain of questions each time.', array['Adults']::text[], '20 minutes in session', 'A late fee is a good starting point for the downward arrow because it is small, factual and produces outsized shame in some clients. Start with the thought about the fee and ask, if that were true, what would it mean about you, four or five times, writing each answer below the last. Stop when the answers start repeating or the client goes quiet. The final line is the belief to work with, not the fee. Run it in session the first time so you can pace it. Watch for a client who jumps to the core belief immediately and skips the chain; the middle rungs are where the thinking traps show.', '[{"id": "f0", "type": "textarea", "label": "The slip: what the fee was for, how much, and the first thought I had about it:"}, {"id": "f1", "type": "textarea", "label": "If that were true, what would it mean about me?"}, {"id": "f2", "type": "textarea", "label": "And if that were true, what would it mean?"}, {"id": "f3", "type": "textarea", "label": "And if that were true?"}, {"id": "f4", "type": "textarea", "label": "The belief at the bottom of the arrow, in my own words:"}, {"id": "f5", "type": "textarea", "label": "How much I believe that belief today, from 0 to 100, and one piece of evidence that complicates it:"}]'::jsonb, array['core beliefs', 'cognitive restructuring', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('sports-commentator-mind-defusion-page', 'Sports Commentator Mind Defusion Page', 'act'::resource_kind, 'A defusion page that casts the running mental commentary as a sports announcer calling every play, so a client can hear it as commentary.', 'Use it to give a client a light way to notice evaluative self-talk as narration rather than as the truth of the game.', array['Adults', 'Teens']::text[], '10 minutes, then during one activity', 'Many clients experience a nonstop play-by-play on their own performance: fumbled that, slow start, crowd is not impressed. The page asks them to give the commentator a name and a voice, write down a typical minute of commentary from an ordinary task, and then do the task while hearing the lines as broadcast rather than verdict. The point is distance, not silence; the commentator keeps talking and the player keeps playing. Watch for a client who tries to argue with the announcer; the move is to let the broadcast run while the hands stay on the task.', '[{"id": "f0", "type": "textarea", "label": "The commentator''s name and voice, and the kind of game they think they are calling:"}, {"id": "f1", "type": "textarea", "label": "A typical minute of commentary during an ordinary task, written as they would say it:"}, {"id": "f2", "type": "textarea", "label": "What the commentary says about my performance that I usually take as fact:"}, {"id": "f3", "type": "textarea", "label": "The task I will do this week while hearing the commentary as broadcast:"}, {"id": "f4", "type": "textarea", "label": "What happened to the task when I stopped arguing with the booth:"}, {"id": "f5", "type": "textarea", "label": "What the player, not the commentator, cares about in this game:"}]'::jsonb, array['defusion', 'core ACT', 'metaphor']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('ten-years-of-tuesdays-values-page', 'Ten Years of Tuesdays Values Page', 'act'::resource_kind, 'A values page asking what ten years of ordinary Tuesdays would look like if lived by what matters rather than by what the mind demands.', 'Use it to move a client from grand life goals to the values that show up on an unremarkable weekday.', array['Adults', 'Teens']::text[], '20 minutes', 'Values work often reaches for the deathbed or the eightieth birthday. This page goes the other way: there will be about five hundred Tuesdays in the next ten years, and almost none of them will be special. The client describes a Tuesday as it goes now, then a Tuesday lived by two or three values they name, in concrete detail, from waking to bed. The gap between the two is the work, and it is made of small things: a text sent, a walk taken, a meeting spoken up in. Watch for a client who writes a fantasy Tuesday with no work or chores; the point is the same day, lived differently.', '[{"id": "f0", "type": "textarea", "label": "A Tuesday as it actually goes now, from waking to bed:"}, {"id": "f1", "type": "textarea", "label": "Two or three values I would want five hundred Tuesdays to add up to:"}, {"id": "f2", "type": "textarea", "label": "The same Tuesday, same job, same chores, lived by those values, hour by hour:"}, {"id": "f3", "type": "textarea", "label": "The smallest difference between the two Tuesdays I could make this week:"}, {"id": "f4", "type": "textarea", "label": "What my mind says about why that will not matter:"}, {"id": "f5", "type": "textarea", "label": "What five hundred of that small difference would add up to:"}]'::jsonb, array['values', 'core ACT', 'committed action']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('cost-of-arguing-with-reality-ledger-page', 'Cost of Arguing With Reality Ledger Page', 'act'::resource_kind, 'A ledger page that tallies what a client spends arguing with a fact that will not change, against what acceptance of it would cost.', 'Use it to help a client weigh the workability of fighting a fixed fact instead of debating whether the fact is fair.', array['Adults']::text[], '20 minutes in session', 'Some clients spend hours a week litigating something that has already happened or cannot be changed: a relative''s illness, a decision an employer made, a sibling''s choice. The ledger does not ask whether it is fair. It asks what the argument costs in hours, sleep, conversations and attention, and what it has bought. Then it asks what accepting the fact as a fact, not as right, would cost and free up. Acceptance here is of the fact, not approval of it. Watch for a client who hears acceptance as giving in; the ledger keeps it as a question of cost.', '[{"id": "f0", "type": "textarea", "label": "The fact I keep arguing with, stated as a fact rather than an injustice:"}, {"id": "f1", "type": "textarea", "label": "What the argument costs me in a typical week: hours, sleep, conversations, attention:"}, {"id": "f2", "type": "textarea", "label": "What the argument has bought me so far:"}, {"id": "f3", "type": "textarea", "label": "What it would cost me to let the fact stand as a fact, without calling it fair:"}, {"id": "f4", "type": "textarea", "label": "What that would free up, and what I would do with it:"}, {"id": "f5", "type": "textarea", "label": "What I would still be allowed to feel about the fact once I stopped arguing:"}]'::jsonb, array['acceptance', 'workability', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('thoughts-as-subtitles-not-the-movie-page', 'Thoughts as Subtitles Not the Movie Page', 'act'::resource_kind, 'A defusion page that treats thoughts as subtitles under the scene, so a client can watch what is happening instead of reading the text.', 'Use it to help a client who lives inside their commentary notice the scene the commentary is about.', array['Adults', 'Teens']::text[], '10 minutes, then one practice a day', 'When a client is fused with thoughts, the subtitles are all they see. The page has them recall a recent moment, write the scene in sensory detail as a camera would record it, then write the subtitles that were running underneath. The practice is to spend one ordinary moment a day deliberately watching the scene while letting the subtitles scroll. It helps to say, there go the subtitles, the way one notices captions on a muted screen. Watch for a client who wants to correct the subtitles; the move is to shift attention to the picture, not to edit the text.', '[{"id": "f0", "type": "textarea", "label": "A recent moment, described as a camera would record it: what was seen, heard, touched:"}, {"id": "f1", "type": "textarea", "label": "The subtitles that were running underneath, word for word:"}, {"id": "f2", "type": "textarea", "label": "Which did I spend the moment watching, the scene or the text?"}, {"id": "f3", "type": "textarea", "label": "One ordinary moment each day this week where I will watch the scene and let the subtitles scroll:"}, {"id": "f4", "type": "textarea", "label": "What I noticed in the scene that the subtitles left out:"}, {"id": "f5", "type": "textarea", "label": "What it was like to let the text run without reading every line:"}]'::jsonb, array['defusion', 'present moment', 'mindfulness']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('willingness-to-feel-bored-page', 'Willingness to Feel Bored Page', 'act'::resource_kind, 'A willingness page for boredom, the feeling many clients will do almost anything to escape, with a short practice of staying in it.', 'Use it to help a client notice what boredom drives them toward and practice being willing to sit in it for a few minutes.', array['Adults', 'Teens']::text[], '10 minutes a day for a week', 'Boredom is a quiet driver of behavior a client wants to change: the snack, the scroll, the text to an ex, the drink. The page asks what they reach for when bored, within how many seconds, and what the boredom feels like in the body before the reaching. The practice is three to five minutes a day of deliberate boredom, sitting with nothing to do, noticing urges arrive and pass. Treat it as willingness practice in a low-stakes feeling. Watch for a client who turns the practice into meditation with a goal; there is no goal but staying.', '[{"id": "f0", "type": "textarea", "label": "What I reach for when I am bored, and how many seconds it usually takes:"}, {"id": "f1", "type": "textarea", "label": "What boredom feels like in my body in the moments before I reach:"}, {"id": "f2", "type": "textarea", "label": "The time and place I will sit with nothing to do for three to five minutes each day:"}, {"id": "f3", "type": "textarea", "label": "The urges that arrived during the sit, and what they wanted me to do:"}, {"id": "f4", "type": "textarea", "label": "What happened to the boredom when I did nothing about it:"}, {"id": "f5", "type": "textarea", "label": "Where else in my week willingness to feel bored might change what I do:"}]'::jsonb, array['willingness', 'core ACT', 'urges']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-a-friends-short-reply-card', 'Check the Facts on a Friend''s Short Reply Card', 'dbt'::resource_kind, 'A Check the Facts card for the one-word text from a friend, walking the prompting event, interpretation and threat before the emotion acts.', 'Use it to give a client a DBT sequence for the short reply that reads as rejection.', array['Adults', 'Teens']::text[], '10 minutes when the reply lands', 'A text that says ok or fine can set off a cascade of emotion the client then acts on. The card follows Check the Facts: name the emotion and its intensity, describe the prompting event in observable terms, list the interpretations and mark which are assumptions, name the threat and how likely it is, picture the catastrophe and whether they could cope, and ask whether the emotion fits the facts. If it fits, problem solve; if not, opposite action. Watch for a client who checks the facts by sending three more texts; the card is done before any reply.', '[{"id": "f0", "type": "textarea", "label": "The emotion, and how intense it is from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "The prompting event, only what the screen shows:"}, {"id": "f2", "type": "textarea", "label": "My interpretations of the reply, with the ones that are assumptions marked:"}, {"id": "f3", "type": "textarea", "label": "The threat I am sensing, and how likely it really is:"}, {"id": "f4", "type": "textarea", "label": "If the worst happened, could I cope, and how:"}, {"id": "f5", "type": "textarea", "label": "Does the emotion and its intensity fit the facts? What will I do instead of replying right now?"}]'::jsonb, array['check the facts', 'core DBT', 'relationships']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('effectively-skill-at-the-dmv-counter-card', 'Effectively Skill at the DMV Counter Card', 'dbt'::resource_kind, 'A card for the Effectively skill in a place that rewards being right over getting it done, practiced in a long line at a government office.', 'Use it to help a client practice doing what works in a frustrating bureaucratic moment instead of what feels justified.', array['Adults']::text[], 'One errand, five minutes to review', 'Effectively is the DBT how skill of doing what works for the goal rather than what proves a point. A government office is an ideal practice ground: slow, rule-bound, and full of chances to be right and still leave without the document. The card asks what the goal of the visit is, what being right would look like, what working would look like, and which the client chose at each friction point. Review afterward which choice got them out the door with what they came for. Watch for a client who confuses effectiveness with passivity; asking a clear question is effective too.', '[{"id": "f0", "type": "textarea", "label": "My goal for this visit, in one line:"}, {"id": "f1", "type": "textarea", "label": "The moments where I could be right instead of effective, as I expect them:"}, {"id": "f2", "type": "textarea", "label": "What being right would look like at the counter, and what it would get me:"}, {"id": "f3", "type": "textarea", "label": "What doing what works would look like, and what it would get me:"}, {"id": "f4", "type": "textarea", "label": "What I actually did at each friction point:"}, {"id": "f5", "type": "textarea", "label": "Did I leave with what I came for? What would I do differently next visit?"}]'::jsonb, array['core DBT', 'mindfulness', 'effectiveness']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-stance-rewrite-of-a-rant-card', 'Nonjudgmental Stance Rewrite of a Rant Card', 'dbt'::resource_kind, 'A card that rewrites a rant the client already said or wrote in the nonjudgmental stance, keeping the facts and the feelings.', 'Use it to practice the nonjudgmentally skill on a real piece of the client''s own speech rather than a made-up example.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients learn nonjudgmental language faster from their own words than from examples. Ask for a recent rant, a message they almost sent or a monologue they delivered in the car, and copy it out. Then rewrite each sentence keeping the observable facts and the feeling but dropping the judgments: lazy becomes did not reply for three days, which left me feeling dismissed. Compare how the two versions land. The feelings often get clearer once the judgments are gone. Watch for a client who hears the exercise as being told their anger was wrong; the anger stays, only the labels go.', '[{"id": "f0", "type": "textarea", "label": "The rant, as I said or wrote it:"}, {"id": "f1", "type": "textarea", "label": "The judgment words in it, circled or listed:"}, {"id": "f2", "type": "textarea", "label": "The same content rewritten: only what happened, what I felt and what I want:"}, {"id": "f3", "type": "textarea", "label": "What got clearer in the rewrite, and what got lost:"}, {"id": "f4", "type": "textarea", "label": "How each version would land on the person it is about:"}, {"id": "f5", "type": "textarea", "label": "One judgment word I use often, and the fact and feeling it usually stands in for:"}]'::jsonb, array['core DBT', 'mindfulness', 'communication']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('contributing-skill-small-favor-for-a-stranger-card', 'Contributing Skill Small Favor for a Stranger Card', 'dbt'::resource_kind, 'A card for the Contributing distraction skill from ACCEPTS, planning one small favor for a stranger on a hard day.', 'Use it to give a client a concrete way to shift attention off distress by doing something for someone else.', array['Adults', 'Teens']::text[], 'Five minutes to plan, one small act', 'Contributing is the ACCEPTS skill clients most often skip because it sounds like volunteering. The card shrinks it: hold a door, return a cart, leave a kind note on a review, let someone merge. Before a hard day the client picks two or three such acts they could do in the course of normal errands, notes their distress before and after, and records what happened to the attention that had been stuck on them. Keep it small and anonymous. Watch for a client who uses it to avoid a problem that needs solving; it is for distress that cannot be solved right now.', '[{"id": "f0", "type": "textarea", "label": "Two or three small favors for strangers I could do during ordinary errands:"}, {"id": "f1", "type": "textarea", "label": "The hard day or moment I will use one of them on:"}, {"id": "f2", "type": "textarea", "label": "My distress before the favor, from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What I did, and how the person responded, if at all:"}, {"id": "f4", "type": "textarea", "label": "My distress afterward, and where my attention went:"}, {"id": "f5", "type": "textarea", "label": "Which favor is easiest to repeat, and when I will use it next:"}]'::jsonb, array['ACCEPTS', 'distress tolerance', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('think-skill-when-a-friend-forgets-to-reply-card', 'THINK Skill When a Friend Forgets to Reply Card', 'dbt'::resource_kind, 'A THINK card for the friend who never answered, walking each letter before the friendship is written off.', 'Use it to help a client apply the THINK skill to a specific lapse by a friend rather than to a grievance in general.', array['Adults', 'Teens']::text[], '10 minutes', 'THINK is the interpersonal skill for reducing anger and resentment toward another person. A friend who did not reply is a good small case. The card walks the client through each letter about that friend and that lapse: what might be going on in their life, how they might be feeling, three benign interpretations, any ways the friend has been trying, and a kind response the client could offer. It does not ask the client to excuse a pattern. Review in session whether this is one lapse or many; THINK is for the former, and DEAR MAN for the latter.', '[{"id": "f0", "type": "textarea", "label": "The friend, what I sent, and how long it has been:"}, {"id": "f1", "type": "textarea", "label": "Think: what might be going on in their life right now?"}, {"id": "f2", "type": "textarea", "label": "Have empathy: how might they be feeling this week?"}, {"id": "f3", "type": "textarea", "label": "Interpretations: three readings of the silence that are not about me:"}, {"id": "f4", "type": "textarea", "label": "Notice: ways they have been trying or showing up lately, even small:"}, {"id": "f5", "type": "textarea", "label": "Kindness: what I could say or do, and whether this is one lapse or a pattern for session:"}]'::jsonb, array['THINK', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('leftovers-and-fridge-cleanout-agreement-for-partners', 'Leftovers and Fridge Cleanout Agreement for Partners', 'couples'::resource_kind, 'A small-friction agreement about leftovers and the fridge, with each partner naming what the fight is really about.', 'Use it to let a couple practice negotiating a tiny recurring conflict before taking the method to a bigger one.', array['Couples']::text[], '20 minutes in session', 'Couples rarely come in about the fridge, but the fridge is where the method can be learned. Each partner writes what bothers them about leftovers and the cleanout, what they think the other partner does not understand, and what the irritation is really about: waste, money, control, being the only one who notices. Then they write one rule each they could live with and pick a trial week. The agreement is less important than the experience of hearing the other''s reason. Watch for a partner who concedes everything to end the conversation; ask for their one rule anyway.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what bothers me about leftovers and the fridge, and what I think you do not see:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what this is really about for me underneath the food:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what bothers me about leftovers and the fridge, and what I think you do not see:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what this is really about for me underneath the food:"}, {"id": "f4", "type": "textarea", "label": "One rule each of us could live with, and the trial week:"}, {"id": "f5", "type": "textarea", "label": "How we will know the trial worked, and when we will revisit it:"}]'::jsonb, array['couples', 'fairness', 'communication']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('phone-at-the-dinner-table-pact-for-partners', 'Phone at the Dinner Table Pact for Partners', 'couples'::resource_kind, 'A pact for partners about phones during meals, with each partner naming what the phone gives them and what they miss when it is out.', 'Use it to help a couple reclaim one shared meal a day without one partner policing the other.', array['Couples']::text[], '15 minutes, then one meal a day', 'Phones at dinner usually produce a monitor and a defendant. The pact asks each partner, separately, what the phone gives them at the table, what they notice about the other''s phone, and what they miss when both screens are up. Then they design the rule together: which meals, where the phones go, what counts as an exception, and what happens when someone slips that is not a lecture. A short ritual to open the meal helps fill the space the phones leave. Watch for a pact that one partner wrote and the other signed; both parts of the sheet need ink.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what my phone gives me at the table, honestly:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I notice about your phone at meals, and what I miss when both are out:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what my phone gives me at the table, honestly:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I notice about your phone at meals, and what I miss when both are out:"}, {"id": "f4", "type": "textarea", "label": "Our pact: which meals, where the phones go, and what counts as an exception:"}, {"id": "f5", "type": "textarea", "label": "What we do when one of us slips, and the small thing we do to start the meal instead:"}]'::jsonb, array['couples', 'connection', 'boundaries']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('inheritance-expectations-talk-sheet-for-partners', 'Inheritance Expectations Talk Sheet for Partners', 'couples'::resource_kind, 'A talk sheet for partners on money they may or may not inherit, surfacing the assumptions each is quietly making about it.', 'Use it to help a couple say out loud what they expect from family money before a death or a will makes it urgent.', array['Couples']::text[], 'Full session', 'Inheritance is the money conversation couples avoid longest, because it involves someone dying and because the assumptions are usually unspoken: that there will be some, that it is theirs, that it will go to the house or the kids or a sibling. The sheet has each partner write what they expect, what they fear, how their family talks about money, and what they would want to do with anything that came. Then they compare. Keep the tone exploratory; nothing is decided here. Watch for a partner who feels the conversation is grasping; naming that feeling is part of the sheet.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I quietly expect about inheritance, from my family or yours:"}, {"id": "f1", "type": "textarea", "label": "Partner A: how my family talks about money and death, and what I learned from that:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I quietly expect about inheritance, from my family or yours:"}, {"id": "f3", "type": "textarea", "label": "Partner B: how my family talks about money and death, and what I learned from that:"}, {"id": "f4", "type": "textarea", "label": "Where our expectations differ, and what surprised each of us:"}, {"id": "f5", "type": "textarea", "label": "What we would want to do with anything that came, and what we would want to do if nothing did:"}]'::jsonb, array['couples', 'money', 'family']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('different-bedtimes-connection-plan-for-partners', 'Different Bedtimes Connection Plan for Partners', 'couples'::resource_kind, 'A plan for partners whose bedtimes are hours apart, protecting a daily point of connection without forcing either onto the other''s clock.', 'Use it to help a night owl and an early sleeper stop fighting about bedtime and build a small ritual that fits both.', array['Couples']::text[], '20 minutes', 'When one partner is asleep by ten and the other is up until two, the fight is rarely about sleep; it is about the one who goes to bed alone and the one who feels dragged. Each partner writes what their bedtime gives them, what they miss, and what they resent. Then they design a tuck-in: ten minutes together at the early partner''s bedtime, with the night owl free afterward, and a morning version if that fits better. Neither clock changes. Watch for the early partner treating the plan as a step toward a shared bedtime; it is the alternative to one.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what my bedtime gives me, what I miss, and what I resent about ours being different:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what my bedtime gives me, what I miss, and what I resent about ours being different:"}, {"id": "f2", "type": "textarea", "label": "The ten minutes we will share at the earlier bedtime, and what happens in them:"}, {"id": "f3", "type": "textarea", "label": "What the night owl is free to do afterward, without comment:"}, {"id": "f4", "type": "textarea", "label": "A morning version, if that fits us better:"}, {"id": "f5", "type": "textarea", "label": "After a week: what the ritual gave us, and what still stings:"}]'::jsonb, array['couples', 'sleep', 'connection']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('wrong-turn-on-the-road-trip-repair-sheet-for-partners', 'Wrong Turn on the Road Trip Repair Sheet for Partners', 'couples'::resource_kind, 'A repair sheet for the missed-exit argument, tracing how a navigation error became a judgment about each other.', 'Use it to help a couple take apart a small car argument and practice a repair they can use on the road.', array['Couples']::text[], '20 minutes after the trip', 'The missed exit argument is a reliable sample of how a couple escalates. Each partner writes what happened in the car in order, the first thing they said, what they heard the other say, and the moment a wrong turn became a statement about who the other person is. Then each writes the repair they wish they had offered within five minutes, and what they needed to hear. Finish with a car rule for next time, including who navigates and what is said when a turn is missed. Watch for a replay of the argument in session; keep both partners on their own column.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what happened in order, and the first thing I said:"}, {"id": "f1", "type": "textarea", "label": "Partner A: the moment the wrong turn became a judgment about you, and what I needed to hear:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what happened in order, and the first thing I said:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the moment the wrong turn became a judgment about you, and what I needed to hear:"}, {"id": "f4", "type": "textarea", "label": "The repair each of us wishes we had offered in the first five minutes:"}, {"id": "f5", "type": "textarea", "label": "Our car rule for next time: who navigates, and what we say when a turn is missed:"}]'::jsonb, array['couples', 'repair', 'conflict']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('sock-puppet-apology-practice-play', 'Sock Puppet Apology Practice Play', 'kids'::resource_kind, 'Two sock puppets act out saying sorry and being told sorry, so a child can rehearse the words and the listening with a parent as puppeteer.', 'Use it to give a child a safe, silly way to practice apologizing and receiving an apology before the next real one.', array['Children']::text[], '20 minutes', 'Apologies are hard for children because the moment is loaded. Two sock puppets take the heat off. The child and parent each make a puppet, then act out a small scene the child chooses, a knocked-over tower or a grabbed toy, with the puppets saying sorry, saying what they would do differently and asking if the other is okay. Then they swap roles so the child practices receiving the apology too. The parent models a short, specific sorry without a lecture. Watch for a parent who scripts every line; let the child''s puppet find its own words, however small.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe your puppet and your grown-up''s puppet, and their names:"}, {"id": "f1", "type": "textarea", "label": "The thing one puppet did that needs a sorry:"}, {"id": "f2", "type": "textarea", "label": "What the sorry puppet says: sorry for what, and what it will do differently:"}, {"id": "f3", "type": "textarea", "label": "What the other puppet says back:"}, {"id": "f4", "type": "textarea", "label": "Now swap: what did it feel like to be the puppet being told sorry?"}, {"id": "f5", "type": "textarea", "label": "Grown-up: a real sorry I said this week, and how I kept it short:"}]'::jsonb, array['children', 'play', 'repair']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('clothespin-feelings-caterpillar-craft', 'Clothespin Feelings Caterpillar Craft', 'kids'::resource_kind, 'A caterpillar made of clothespins, each painted a feeling color, that a child clips in order to show how a day''s feelings lined up.', 'Use it to help a child show the sequence of feelings in a day rather than just the biggest one.', array['Children']::text[], '30 minutes to build, one minute a day to use', 'Children often report one feeling for a whole day. The caterpillar shows a day as a sequence. The child paints eight to ten wooden clothespins, each a color for a feeling they name, and the parent helps make a key. At bedtime the child clips the pins to a ribbon in the order the feelings came, then tells the caterpillar''s story from head to tail. The parent listens and asks what happened between two colors, not why the child felt that way. Watch for a child who only clips the pleasant colors to please the parent; make sure the key has room for mad and sad.', '[{"id": "f0", "type": "textarea", "label": "The colors on my caterpillar and the feeling each one means:"}, {"id": "f1", "type": "textarea", "label": "Today''s caterpillar from head to tail, in order:"}, {"id": "f2", "type": "textarea", "label": "What happened between the first color and the second one:"}, {"id": "f3", "type": "textarea", "label": "The color that was on the longest today:"}, {"id": "f4", "type": "textarea", "label": "Grown-up: a question I asked about the caterpillar that was not why:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: what I noticed about the order of feelings this week:"}]'::jsonb, array['children', 'craft', 'emotion identification']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('pillow-mountain-climb-and-rest-play', 'Pillow Mountain Climb and Rest Play', 'kids'::resource_kind, 'A living room game where a child climbs a pillow mountain, rests at the top with slow breaths and climbs down, so big energy ends in calm.', 'Use it to give a child with a lot of body energy a play that ends in rest instead of a crash.', array['Children']::text[], '15 minutes', 'Some children need to move hard before they can settle, and the trouble is the stop. Pillow mountain builds the stop into the game. The parent and child pile every pillow and cushion into a mountain, the child climbs it with as much effort as they like, and at the summit the rule is three slow dragon breaths while looking out over the kingdom. Then a slow climb down and a rest at base camp. Repeat two or three times. The parent climbs too and breathes loudly at the top. Watch for a parent who only enforces the breaths; the climb is what earns the child''s cooperation.', '[{"id": "f0", "type": "textarea", "label": "Draw your pillow mountain and name it:"}, {"id": "f1", "type": "textarea", "label": "How you climb: fast, slow, like which animal?"}, {"id": "f2", "type": "textarea", "label": "At the top: three slow breaths, and what you can see from the summit:"}, {"id": "f3", "type": "textarea", "label": "How your body feels at base camp after the climb down:"}, {"id": "f4", "type": "textarea", "label": "Grown-up: did I climb and breathe too, or only direct?"}, {"id": "f5", "type": "textarea", "label": "Grown-up: how the rest after the game compared with rest after other rough play:"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('flashlight-shadow-brave-animals-play', 'Flashlight Shadow Brave Animals Play', 'kids'::resource_kind, 'A bedtime shadow game where a child and parent make brave animals on the wall with a flashlight and give each one a brave thing to say.', 'Use it to help a child who fears the dark turn the flashlight and the shadows into something they control.', array['Children']::text[], '10 minutes at bedtime', 'For a child afraid of the dark, shadows are the enemy. This play makes the child the one who casts them. With the lights off and a flashlight, parent and child make hand-shadow animals on the wall, name each one, and give it a brave sentence to say to the dark. The child holds the flashlight and decides when the animals appear and disappear. End with the bravest animal standing guard and the flashlight within reach. The parent keeps it playful and does not argue the fear away. Watch for the game running long and winding the child up; two or three animals is plenty.', '[{"id": "f0", "type": "textarea", "label": "Draw the shadow animals you made and their names:"}, {"id": "f1", "type": "textarea", "label": "What each brave animal says to the dark:"}, {"id": "f2", "type": "textarea", "label": "The bravest animal, and where it stands guard:"}, {"id": "f3", "type": "textarea", "label": "What it felt like to be the one holding the flashlight:"}, {"id": "f4", "type": "textarea", "label": "Grown-up: how I kept it short and let my child run the light:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: what bedtime was like after the game, compared with other nights:"}]'::jsonb, array['children', 'play', 'fear']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('rainstick-shaker-calm-sound-craft', 'Rainstick Shaker Calm Sound Craft', 'kids'::resource_kind, 'A rainstick made from a cardboard tube, foil and rice that a child tips slowly to make a sound that lasts as long as a slow breath.', 'Use it to give a child a homemade calm-down object with a sound that paces their breathing.', array['Children']::text[], '30 minutes to build', 'A rainstick is a calm tool a child can build and own. Parent and child seal one end of a long cardboard tube, crumple a long strip of foil into a loose spiral inside, pour in rice or lentils, seal the other end and decorate the outside. Tipped slowly, the rice falls through the foil for several seconds. The practice is to breathe in while the sound falls one way and out while it falls back. The parent demonstrates slow tipping; fast shaking is allowed but is a different game. Watch for the stick becoming a weapon in a sibling fight; it lives in the calm corner.', '[{"id": "f0", "type": "textarea", "label": "Decorate your rainstick here first: colors, patterns, a name:"}, {"id": "f1", "type": "textarea", "label": "How long the rain lasts when you tip it slowly, counted in breaths:"}, {"id": "f2", "type": "textarea", "label": "Breathe in with the rain one way, out with the rain the other: how many turns until you feel slower?"}, {"id": "f3", "type": "textarea", "label": "Where your rainstick lives, and when you will use it:"}, {"id": "f4", "type": "textarea", "label": "Grown-up: how I showed slow tipping without taking the stick away:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: a moment this week the rainstick helped, or did not:"}]'::jsonb, array['children', 'craft', 'breathing']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('sound-effects-story-orchestra-game', 'Sound Effects Story Orchestra Game', 'game'::resource_kind, 'One player tells a short story and everyone else supplies the sound effects, with a debrief on listening and letting go of looking silly.', 'Use it to warm up a group that is self-conscious, giving everyone a part that is loud, playful and impossible to get wrong.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Rules: one player is the narrator and tells a simple story of about two minutes, a walk in the rain, a kitchen disaster, a trip to the zoo. Every other player is the orchestra and provides every sound effect as it comes: footsteps, doors, animals, weather. Then the narrator role passes. Three or four rounds. Debrief: what it took to make a noise in front of the group, who held back and why, and what happened to self-consciousness once everyone was being ridiculous. Watch for a member who refuses; give them the conductor role, pointing to who plays.', '[{"id": "f0", "type": "textarea", "label": "Sounds I made during the stories, and the one I was proudest of:"}, {"id": "f1", "type": "textarea", "label": "The moment I held back a sound, and what I was worried about:"}, {"id": "f2", "type": "textarea", "label": "What it was like to narrate and have the group fill in my world:"}, {"id": "f3", "type": "textarea", "label": "What happened to feeling silly once everyone was doing it:"}, {"id": "f4", "type": "textarea", "label": "Where else in my week I hold back for fear of looking silly:"}, {"id": "f5", "type": "textarea", "label": "One small sound I could make in that place:"}]'::jsonb, array['game', 'group', 'connection']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('charades-of-everyday-stressors-game', 'Charades of Everyday Stressors Game', 'game'::resource_kind, 'Players act out ordinary stressors, a jammed printer, a long hold, a late bus, and the group guesses, then compares how they cope.', 'Use it to get a group laughing at shared daily stress and comparing coping in a low-pressure way.', array['Groups', 'Teens']::text[], '25 minutes', 'Rules: write everyday stressors on slips, one per slip: traffic, a slow checkout, a group project, a dead phone, a toddler refusing shoes. Players draw a slip and act it out without words while the group guesses within a minute. After each correct guess, a thirty-second round: everyone says one thing they do when that happens to them. Ten to twelve slips. Debrief: which stressor was the easiest to act because everyone knows the look of it, which coping moves came up most, and one move someone heard that they want to try. Watch for the coping round becoming advice; it is a list, not a fix.', '[{"id": "f0", "type": "textarea", "label": "Stressors I acted out or guessed, and the one that got the biggest laugh:"}, {"id": "f1", "type": "textarea", "label": "The stressor that was easiest to act because everyone recognized it:"}, {"id": "f2", "type": "textarea", "label": "What I said I do when it happens to me:"}, {"id": "f3", "type": "textarea", "label": "A coping move I heard from someone else that I want to try:"}, {"id": "f4", "type": "textarea", "label": "A stressor that was on a slip and did not feel funny to me, and why:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about my body during the acting round:"}]'::jsonb, array['game', 'group', 'stress']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('count-to-twenty-without-overlapping-game', 'Count to Twenty Without Overlapping Game', 'game'::resource_kind, 'The group counts to twenty aloud with no order or signals, restarting when voices overlap, then talks about patience and reading a room.', 'Use it to build a group''s tolerance for silence and uncertainty and to open a talk about rushing in versus holding back.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: the group sits in a circle with eyes closed or looking at the floor. Anyone may say the next number at any time. If two people speak at once, the count restarts at one. There is no order, no pointing and no leader. The goal is to reach twenty. It usually takes several attempts and a lot of silence. Debrief: who jumped in and who waited, what it felt like in a long pause, how it felt to be the one who caused a restart, and what the group did differently on the attempt that worked. Watch for a member who stops participating after causing a restart; name how quickly the group moved on.', '[{"id": "f0", "type": "textarea", "label": "Was I someone who jumped in or someone who waited? What told me when to speak?"}, {"id": "f1", "type": "textarea", "label": "What a long silence felt like in my body:"}, {"id": "f2", "type": "textarea", "label": "What it felt like to cause a restart, and what the group did about it:"}, {"id": "f3", "type": "textarea", "label": "What changed on the attempt that reached twenty:"}, {"id": "f4", "type": "textarea", "label": "Where in my life I rush in, and where I hold back too long:"}, {"id": "f5", "type": "textarea", "label": "One pause I could tolerate this week that I usually fill:"}]'::jsonb, array['game', 'group', 'uncertainty']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('spot-the-difference-perspective-game', 'Spot the Difference Perspective Game', 'game'::resource_kind, 'Two players describe the same picture from memory and the group lists the differences, showing how two honest accounts diverge.', 'Use it to show a group that two people can see the same moment differently without either lying.', array['Groups', 'Teens', 'Couples']::text[], '20 minutes', 'Rules: two players look at the same busy picture, or watch the same one-minute scene acted by two others, for thirty seconds. They then separately describe what they saw to the group, which lists every difference between the two accounts. Three or four pairs. Debrief: how many differences there were, whether either player was wrong, what each one noticed first and why that might be, and where in the group''s lives two honest accounts of the same event have caused a fight. Watch for a pair that argues about who was right; the differences list is the point, not the winner.', '[{"id": "f0", "type": "textarea", "label": "What I noticed first in the picture or scene, and what I missed entirely:"}, {"id": "f1", "type": "textarea", "label": "The differences between my account and my partner''s:"}, {"id": "f2", "type": "textarea", "label": "Was either of us wrong? What was each of us paying attention to?"}, {"id": "f3", "type": "textarea", "label": "A time two honest accounts of the same event caused a fight in my life:"}, {"id": "f4", "type": "textarea", "label": "What I would ask the other person now that I have played this:"}, {"id": "f5", "type": "textarea", "label": "What I will remember next time my version and someone else''s do not match:"}]'::jsonb, array['game', 'group', 'perspective']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('category-snap-quick-think-game', 'Category Snap Quick Think Game', 'game'::resource_kind, 'A fast circle game naming items in a category on a beat, with a debrief on freezing, blurting and what the mind does under a clock.', 'Use it to give a group a quick, high-energy round that surfaces how each person handles pressure to perform.', array['Groups', 'Teens', 'Children']::text[], '15 minutes', 'Rules: the group claps a steady slow beat. The leader names a category, fruits, things in a kitchen, feelings, and on each beat the next player in the circle names one item. Repeats and misses mean that player picks the next category. No one is out. Six to eight categories, speeding up slightly each time. Debrief: who froze and who blurted, what the mind said in the half-second before their turn, how it felt when someone else missed, and what the group would say about mistakes. Watch for competitive members; the only cost of a miss is choosing the next category.', '[{"id": "f0", "type": "textarea", "label": "Did I freeze or blurt when my beat came? What did my mind say in the half second before?"}, {"id": "f1", "type": "textarea", "label": "How it felt when I missed, and what the group actually did:"}, {"id": "f2", "type": "textarea", "label": "How it felt watching someone else miss:"}, {"id": "f3", "type": "textarea", "label": "A category that was easy for me and one that emptied my head:"}, {"id": "f4", "type": "textarea", "label": "Where in my week a small clock makes my mind go blank:"}, {"id": "f5", "type": "textarea", "label": "What I learned about how the group treats a miss:"}]'::jsonb, array['game', 'group', 'attention']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('crowded-holiday-store-steadiness-plan-sheet', 'Crowded Holiday Store Steadiness Plan Sheet', 'worksheet'::resource_kind, 'A plan for a crowded seasonal store: the time of day, the entrance, the exits, the grounding object in a pocket and the signal to leave.', 'Use it to help a client who goes still or flooded in crowds get through a necessary store trip with a plan they made in advance.', array['Adults', 'Teens']::text[], '15 minutes before the trip', 'Holiday crowds combine noise, bodies close behind, blocked exits and sudden sounds, which is a lot for a client whose system still scans for threat. The sheet keeps the trip small: the quietest hour, the entrance nearest what they need, where the exits are, what they will hold in a pocket, who comes along or is on the phone, and the private signal that means we are leaving now with no explanation owed. Leaving early is a success on this sheet. Review afterward what the body did and what helped. Watch for a client who plans to white-knuckle it; the signal to leave is the most important line.', '[{"id": "f0", "type": "textarea", "label": "The store, the quietest hour I can go, and the one or two things I actually need:"}, {"id": "f1", "type": "textarea", "label": "The entrance nearest those things, and where the exits are:"}, {"id": "f2", "type": "textarea", "label": "What I will hold or touch in my pocket to stay in the present:"}, {"id": "f3", "type": "textarea", "label": "Who comes with me or stays on the phone, and my signal that means we leave now:"}, {"id": "f4", "type": "textarea", "label": "What I will do in the first five minutes back in the car:"}, {"id": "f5", "type": "textarea", "label": "After: what my body did, what helped, and what I would change:"}]'::jsonb, array['PTSD and trauma', 'stabilizing', 'planning', 'grounding']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('nowhere-is-safe-overgeneralization-check-sheet', 'Nowhere Is Safe Overgeneralization Check Sheet', 'cbt'::resource_kind, 'A sheet that takes the thought nowhere is safe and checks it against specific places and hours in the client''s week, one at a time.', 'Use it to help a client whose sense of danger has spread everywhere find the specific places where their body already knows otherwise.', array['Adults', 'Teens']::text[], '20 minutes in session', 'After something terrible, the mind protects by generalizing: if it happened there, it can happen anywhere. The sheet does not argue. It lists ten specific places and times from the client''s week, the kitchen at breakfast, the car in the driveway, the friend''s couch, and for each the client rates felt danger and actual danger separately, and notes what their body does there. The spread between the two columns, place by place, is the conversation. Keep it in session so you can slow it down. Watch for a client who rates every place the same; ask about the one place they fall asleep most easily.', '[{"id": "f0", "type": "textarea", "label": "The thought as it shows up, in my words:"}, {"id": "f1", "type": "textarea", "label": "Ten specific places and times in my week, listed plainly:"}, {"id": "f2", "type": "textarea", "label": "For each place: how dangerous it feels, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "For each place: how dangerous I would say it is for a friend, 0 to 100:"}, {"id": "f4", "type": "textarea", "label": "What my body does in the place with the biggest gap between the two numbers:"}, {"id": "f5", "type": "textarea", "label": "A slightly more specific version of the thought that fits the list:"}]'::jsonb, array['PTSD and trauma', 'thinking traps', 'safety', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('scar-not-wound-noticing-page', 'Scar Not Wound Noticing Page', 'act'::resource_kind, 'A self-as-context page on the difference between a scar, which is carried, and a wound, which is open, without describing the injury.', 'Use it to help a client notice the part of them that has been there through the whole story and is still here now.', array['Adults']::text[], '20 minutes in session', 'This page stays with the present and never asks for the event. A scar is proof of healing and of something that happened; a wound is still open. The client notices which parts of the story feel like scar and which still feel like wound, in general terms, and then turns to the one who has carried both: the self that was there before, during and after, and is sitting in the room now. Write what that observer notices about today''s body, breath and room. Keep the pacing slow. Watch for a client who treats scar as meaning over it; a scar is carried, not erased.', '[{"id": "f0", "type": "textarea", "label": "Without describing what happened: which parts feel like scar, carried but closed, and which still feel like wound:"}, {"id": "f1", "type": "textarea", "label": "The one who has been there through all of it and is here now: what do they notice in this room?"}, {"id": "f2", "type": "textarea", "label": "What this body can do today that it could not do at the worst point:"}, {"id": "f3", "type": "textarea", "label": "What the observer would say to the wound, and to the scar:"}, {"id": "f4", "type": "textarea", "label": "One ordinary thing I will do this week as the person carrying both:"}, {"id": "f5", "type": "textarea", "label": "What I need from my clinician when a wound part opens in session:"}]'::jsonb, array['PTSD and trauma', 'self-as-context', 'stabilizing', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('cold-can-from-the-fridge-grounding-card', 'Cold Can From the Fridge Grounding Card', 'dbt'::resource_kind, 'A grounding card that uses a cold can from the fridge against the wrists and neck to bring the body back to the room in under a minute.', 'Use it to give a client a grounding tool that is always in the kitchen and takes under a minute.', array['Adults', 'Teens']::text[], 'One minute, when the present slips', 'Cold is one of the fastest routes back to the present and most clients have a fridge. The card: take out a cold can or bottle, hold it in both hands, press it to the inside of each wrist for ten slow counts, then the back of the neck, naming aloud the room, the date and one thing in view. The cold gives the attention something undeniable to land on. Practice it in a calm moment first so the sequence is familiar. It is a return to the room, not a replacement for the work you do together. Watch for a client who uses ice directly on skin for long stretches; a can from the fridge is cold enough.', '[{"id": "f0", "type": "textarea", "label": "Where the cold can lives, and when I will practice this once while calm:"}, {"id": "f1", "type": "textarea", "label": "The sequence in my own words: hands, wrists, neck, room, date, one thing I see:"}, {"id": "f2", "type": "textarea", "label": "What the cold did to my attention the first time:"}, {"id": "f3", "type": "textarea", "label": "The words I say aloud about the room and the date:"}, {"id": "f4", "type": "textarea", "label": "Moments this week the card brought me back, and how long it took:"}, {"id": "f5", "type": "textarea", "label": "What I do next after I am back in the room:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('heartbeat-drum-slow-down-play', 'Heartbeat Drum Slow Down Play', 'kids'::resource_kind, 'A child drums their own heartbeat on a pot, then slows the drumming to lead the body to a calmer rhythm while a parent drums along.', 'Use it to give a child who gets stuck in a racing body a playful way to notice their heartbeat and slow it with a parent beside them.', array['Children']::text[], '10 minutes', 'A child who has been through frightening things may live in a fast body without knowing it. In this play the child finds their heartbeat with a hand on their chest, drums that rhythm on an upturned pot or box, and the parent copies. Then the parent slows the beat a little at a time and the child follows, breathing with the drum until both are slow. The parent never asks about what happened, only about the drum. Watch for a child whose beat does not settle; stop early and stay close. If a child discloses abuse or harm during any play, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Find your heartbeat with your hand: fast, medium or slow today? Draw it as dots:"}, {"id": "f1", "type": "textarea", "label": "Drum it on your pot. Did your grown-up match you?"}, {"id": "f2", "type": "textarea", "label": "Slow the drum together: how many slow beats until your body followed?"}, {"id": "f3", "type": "textarea", "label": "Where in your body you felt the slowing first:"}, {"id": "f4", "type": "textarea", "label": "Grown-up: how I followed my child''s beat before leading it slower:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: when I will offer the drum this week, and what I noticed about my own beat:"}]'::jsonb, array['PTSD and trauma', 'children', 'grounding', 'play']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('unread-voicemail-avoidance-steps-sheet', 'Unread Voicemail Avoidance Steps Sheet', 'worksheet'::resource_kind, 'A step sheet for the voicemails a client cannot bring themselves to play, from counting them to listening with a plan for each kind of news.', 'Use it to help a client clear a backlog of avoided voicemails and notice what the avoidance was protecting them from.', array['Adults', 'Teens']::text[], '20 minutes', 'Unplayed voicemails accumulate the way unopened mail does, and each one grows heavier. The sheet has the client count them, guess who each is from and what it might say, rate the dread, and then play them in a chosen order, easiest first, with a plan written in advance for the three kinds of news: nothing, something to do, something upsetting. After each, they write what it actually was. The gap between guesses and reality is the lesson. Watch for a client who deletes unheard to make the number zero; the sheet counts listening, not deleting.', '[{"id": "f0", "type": "textarea", "label": "How many voicemails are waiting, and how long the oldest has been there:"}, {"id": "f1", "type": "textarea", "label": "For each: who I think it is from, what I think it says, and my dread from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "My plan if a message is nothing, if it needs something from me, and if it is upsetting:"}, {"id": "f3", "type": "textarea", "label": "The order I will listen in, easiest first, and when:"}, {"id": "f4", "type": "textarea", "label": "What each message actually was:"}, {"id": "f5", "type": "textarea", "label": "What the avoidance was protecting me from, and what it cost:"}]'::jsonb, array['anxiety', 'avoidance', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('package-marked-delivered-but-missing-thought-record', 'Package Marked Delivered but Missing Thought Record', 'cbt'::resource_kind, 'A thought record for the package marked delivered that is not on the porch, catching the leap from missing to stolen to unsafe.', 'Use it to practice a thought record on a small, common jolt before using it on the bigger ones.', array['Adults', 'Teens']::text[], '10 minutes', 'A missing package is a perfect small practice case: the facts are limited, the mind fills them fast, and the outcome arrives within a day or two. The record captures the situation, the first thought, the feeling and its strength, the evidence for and against, and the list of ordinary explanations: wrong porch, early scan, a neighbor, the back door. The client writes a balanced thought and then, when the package turns up or does not, records the outcome against the prediction. Watch for a client who skips the record because the package arrived; the record is for the hour before it did.', '[{"id": "f0", "type": "textarea", "label": "What the tracking says, and what I actually see at the door:"}, {"id": "f1", "type": "textarea", "label": "The first thought, and where it went from there:"}, {"id": "f2", "type": "textarea", "label": "What I feel, and how strong it is from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Evidence for the thought, facts only, and evidence against:"}, {"id": "f4", "type": "textarea", "label": "Four ordinary explanations and how likely each is:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought now, and what actually happened to the package:"}]'::jsonb, array['anxiety', 'thought record', 'uncertainty', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('mind-as-an-overprotective-travel-agent-page', 'Mind as an Overprotective Travel Agent Page', 'act'::resource_kind, 'A defusion page that casts the anxious mind as a travel agent who cancels every trip for safety, so the client can thank it and book anyway.', 'Use it to help a client see worry''s cancellations as a well-meaning service they can decline.', array['Adults', 'Teens']::text[], '15 minutes', 'The anxious mind means well. On this page it is a travel agent who has read every warning and cancels every booking: the party, the new job, the drive, the date. The client writes the trips the agent has canceled this year and the warning it gave for each, then writes what they would say to a real agent who did that: thank you, I see the risk, book it anyway. The practice is to notice the cancellation notice and respond as the customer, not the agent. Watch for a client who wants to fire the agent; it does not leave, and the goal is to keep booking while it talks.', '[{"id": "f0", "type": "textarea", "label": "Trips my mind has canceled this year, big and small, and the warning it gave for each:"}, {"id": "f1", "type": "textarea", "label": "The trip I most wish had not been canceled:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a real travel agent who canceled a trip for me without asking:"}, {"id": "f3", "type": "textarea", "label": "The next booking my agent is likely to try to cancel, and when:"}, {"id": "f4", "type": "textarea", "label": "My line for the agent: thank you, I see the risk, and then what I will do:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the agent''s voice once I stopped treating it as the boss:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('check-the-facts-when-the-landlord-says-we-need-to-talk-card', 'Check the Facts When the Landlord Says We Need to Talk Card', 'dbt'::resource_kind, 'A Check the Facts card for an ambiguous message from a landlord, employer or school that sets off a day of dread before any facts arrive.', 'Use it to give a client a DBT sequence for the hours between an ominous message and the actual conversation.', array['Adults']::text[], '10 minutes when the message arrives', 'We need to talk, from anyone with power over a client''s housing, job or child, can wipe out a day. The card walks Check the Facts: the emotion and its intensity, the prompting event as the exact words received, the interpretations with assumptions marked, the threat and its real probability, the catastrophe and whether they could cope with it, and whether the emotion fits the facts so far. Then a plan for the hours until the talk that is not rehearsing the disaster. Watch for a client who writes back demanding to know now; the card asks for one calm reply that sets a time.', '[{"id": "f0", "type": "textarea", "label": "The emotion, and how intense it is from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "The exact words I received, nothing added:"}, {"id": "f2", "type": "textarea", "label": "My interpretations, with the ones that are assumptions marked:"}, {"id": "f3", "type": "textarea", "label": "The worst case, how likely it really is, and how I would cope if it happened:"}, {"id": "f4", "type": "textarea", "label": "Does the emotion fit the facts so far? What intensity would fit?"}, {"id": "f5", "type": "textarea", "label": "One calm reply that sets a time, and what I will do with the hours until then:"}]'::jsonb, array['anxiety', 'check the facts', 'core DBT', 'uncertainty']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('fortune-teller-versus-fact-checker-team-game', 'Fortune Teller Versus Fact Checker Team Game', 'game'::resource_kind, 'One team makes dire predictions about everyday scenarios and the other fact-checks them, with points for the most grounded answer.', 'Use it to let a group practice catching catastrophic predictions in a fast, funny format before trying it on their own.', array['Groups', 'Teens']::text[], '25 minutes', 'Rules: split into two teams. The leader reads an everyday scenario: your friend has not texted back, you have a headache before a trip, the boss scheduled a meeting. The fortune tellers have thirty seconds to produce the most dramatic prediction they can, played for laughs. The fact checkers then have a minute to list what is actually known, three other possible outcomes and the most likely one. The group votes on which team was more convincing; the fact checkers usually win. Debrief: which role felt more familiar, and which fortune teller lines sounded like something in their own head.', '[{"id": "f0", "type": "textarea", "label": "The fortune teller prediction that got the biggest laugh, and the one that sounded like my own mind:"}, {"id": "f1", "type": "textarea", "label": "What it was like to be a fact checker: what did I find easiest to list?"}, {"id": "f2", "type": "textarea", "label": "Which role felt more familiar to me, and when in my week I play it:"}, {"id": "f3", "type": "textarea", "label": "A scenario from my own life I would hand to the fact checkers:"}, {"id": "f4", "type": "textarea", "label": "Three outcomes for that scenario, and the most likely one:"}, {"id": "f5", "type": "textarea", "label": "One fact checker question I can ask myself the next time the fortune teller starts:"}]'::jsonb, array['anxiety', 'game', 'predictions', 'group']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('sunlight-minutes-before-noon-log-sheet', 'Sunlight Minutes Before Noon Log Sheet', 'worksheet'::resource_kind, 'A one-week log of minutes spent in outdoor light before noon, with the mood, the obstacle and the smallest version that still counts.', 'Use it to help a client with low mood add one morning anchor and notice what it does over a week.', array['Adults', 'Teens']::text[], 'Five minutes a day for a week', 'Morning light is one of the simplest anchors a flat week can have, and one of the first to disappear when mood drops. The log asks for the minutes outside before noon, where the client was, their mood at midday from 0 to 10, and what got in the way on days with zero. The smallest version counts: coffee on the step, a walk to the mailbox, standing in an open doorway. Review the week for any relationship between the minutes and the midday number without promising one. Watch for a client who turns it into a step goal; the unit is minutes in light, not distance.', '[{"id": "f0", "type": "textarea", "label": "Each morning: minutes outside before noon, and where I was:"}, {"id": "f1", "type": "textarea", "label": "Each day: my midday mood from 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "On the zero days: what got in the way?"}, {"id": "f3", "type": "textarea", "label": "The smallest version that still counts for me on a hard morning:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the days with more light, if anything:"}, {"id": "f5", "type": "textarea", "label": "The morning anchor I will keep next week, and what will make it easier:"}]'::jsonb, array['depression', 'routines', 'behavioral activation', 'self-monitoring']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('my-friends-are-tired-of-me-thought-record', 'My Friends Are Tired of Me Thought Record', 'cbt'::resource_kind, 'A thought record for the belief that friends are tired of the client, checked against what friends have actually said and done.', 'Use it to help a client test the belief that drives them to withdraw from the people most likely to help.', array['Adults', 'Teens']::text[], '15 minutes', 'The belief that friends are worn out by the client is one of the most efficient engines of isolation in low mood. The record follows the standard columns and then adds two: what each named friend has actually said or done in the past month, and what the client would conclude about a friend who said the same about themselves. Evidence has to be observable, not sensed. Finish with a balanced thought and one small contact to make before the next session. Watch for a client who treats a friend being busy as proof; busy goes in a column of its own.', '[{"id": "f0", "type": "textarea", "label": "The thought, with the names of the friends it is about:"}, {"id": "f1", "type": "textarea", "label": "What I feel, and how strong it is from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What each of those friends has actually said or done in the last month:"}, {"id": "f3", "type": "textarea", "label": "Evidence for the thought that a camera could record, and evidence against:"}, {"id": "f4", "type": "textarea", "label": "If a friend told me their friends were tired of them, what would I say?"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and one small contact I will make before next session:"}]'::jsonb, array['depression', 'thought record', 'core CBT', 'relationships']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('taking-the-mood-along-for-the-errand-page', 'Taking the Mood Along for the Errand Page', 'act'::resource_kind, 'A willingness page that plans one errand done with the low mood riding along, instead of waiting for the mood to lift first.', 'Use it to help a client act on a value while feeling flat, and notice what the mood does once they are moving.', array['Adults', 'Teens']::text[], '15 minutes, then one errand', 'Many clients are waiting to feel better before doing anything, and the waiting is where the mood sets. This page picks one errand tied to something that matters, the pharmacy for a parent, the library for a child, groceries for the week, and plans to do it with the mood along, as one would take a tired dog on a walk. The client writes what the mood will say in the car, what they will do with their hands and feet anyway, and afterward what the mood did between the door and home. Watch for a client who picks an errand with no value attached; ask who or what it is for.', '[{"id": "f0", "type": "textarea", "label": "The errand, and who or what it is for:"}, {"id": "f1", "type": "textarea", "label": "What the mood is likely to say on the way out the door and in the car:"}, {"id": "f2", "type": "textarea", "label": "What my hands and feet will do anyway, step by step:"}, {"id": "f3", "type": "textarea", "label": "Where the mood sat during the errand: beside me, on top of me, somewhere behind?"}, {"id": "f4", "type": "textarea", "label": "What the mood did between leaving and getting home:"}, {"id": "f5", "type": "textarea", "label": "The next errand I could take the mood along on:"}]'::jsonb, array['depression', 'willingness', 'committed action', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-i-have-nothing-to-offer-card', 'Check the Facts on I Have Nothing to Offer Card', 'dbt'::resource_kind, 'A Check the Facts card for the thought I have nothing to offer, applied to one invitation the client is about to turn down.', 'Use it to interrupt a withdrawal decision with a DBT fact check tied to a real moment rather than a global belief.', array['Adults', 'Teens']::text[], '10 minutes before declining', 'I have nothing to offer is a global verdict that arrives as a feeling and gets acted on as a fact. The card narrows it to one invitation or request the client is about to decline, then runs Check the Facts: the emotion and intensity, the event as it happened, the interpretations with assumptions marked, what the other person actually asked for, whether a quiet presence would meet it, and whether the emotion fits. If the facts say yes, the client goes, perhaps for a shorter time. Watch for the card becoming a reason to over-commit; it is about one invitation, and leaving early is allowed.', '[{"id": "f0", "type": "textarea", "label": "The invitation or request I am about to turn down, and who it is from:"}, {"id": "f1", "type": "textarea", "label": "The emotion, and how intense it is from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What the person actually asked for, in their words:"}, {"id": "f3", "type": "textarea", "label": "My interpretation of what they want from me, with assumptions marked:"}, {"id": "f4", "type": "textarea", "label": "Would a quiet, short version of me meet what they asked for? What facts say so?"}, {"id": "f5", "type": "textarea", "label": "Does the emotion fit the facts? What I will do, and for how long:"}]'::jsonb, array['depression', 'check the facts', 'core DBT', 'connection']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('household-takeover-without-scorekeeping-for-partners', 'Household Takeover Without Scorekeeping for Partners', 'couples'::resource_kind, 'A sheet for when one partner is in a low stretch and the other carries the house, naming what is carried, for how long and how it returns.', 'Use it to help a couple survive a depressive stretch without one partner building resentment or the other building debt.', array['Couples']::text[], '30 minutes in session', 'When one partner''s mood drops, the other often absorbs the household quietly, and a quiet ledger starts. The sheet makes it explicit and temporary. The carrying partner writes what they have taken on and what is becoming too much; the partner in the low stretch writes what they can still do, even small, and what they want to hear instead of a tally. Together they set a review date, one task that returns first, and a sentence for the carrying partner to use when they are at their limit. Watch for the low partner reading the sheet as an invoice; the review date keeps it a loan, not a debt.', '[{"id": "f0", "type": "textarea", "label": "Carrying partner: what I have taken on in the last few weeks, and what is becoming too much:"}, {"id": "f1", "type": "textarea", "label": "Carrying partner: what I want my partner to know that is not a score:"}, {"id": "f2", "type": "textarea", "label": "Partner in the low stretch: what I can still do this week, even small, and what I want to hear instead of a tally:"}, {"id": "f3", "type": "textarea", "label": "Partner in the low stretch: what I notice you carrying, and what it is like to watch:"}, {"id": "f4", "type": "textarea", "label": "The one task that comes back first, and the review date we set:"}, {"id": "f5", "type": "textarea", "label": "The sentence the carrying partner can say when they are at their limit, and what happens next:"}]'::jsonb, array['depression', 'couples', 'support', 'fairness']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('returns-pile-deadline-tracker-sheet', 'Returns Pile Deadline Tracker Sheet', 'worksheet'::resource_kind, 'A tracker for the pile of things to return, each with its deadline, location and single next step, so the window stops closing unnoticed.', 'Use it to help a client with executive function struggles turn a shame pile into a short list with dates.', array['Adults', 'Teens']::text[], '15 minutes to set up, two minutes a day', 'The returns pile is a specific kind of clutter: every item has a closing window, and missing it costs money and self-respect. The sheet lists each item, where it is physically, the return deadline, whether a label or receipt is needed, and the one next step that takes under five minutes. Then the client picks the item with the nearest deadline and does its step today. One item a day beats a planned Saturday that never comes. Review in session which steps stalled and why. Watch for a client who adds organizing the pile as a step; the pile stays messy, the items leave.', '[{"id": "f0", "type": "textarea", "label": "Every item in the pile: what it is, where it is right now, and the deadline:"}, {"id": "f1", "type": "textarea", "label": "For each: do I need a receipt, a label, a box or a trip?"}, {"id": "f2", "type": "textarea", "label": "The one next step for each that takes under five minutes:"}, {"id": "f3", "type": "textarea", "label": "The item with the nearest deadline, and the step I will do today:"}, {"id": "f4", "type": "textarea", "label": "Each day: the step I did, and what got in the way if I did not:"}, {"id": "f5", "type": "textarea", "label": "What this pile has cost me so far, and what I will do with the space when it is gone:"}]'::jsonb, array['ADHD', 'executive function', 'planning', 'money']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('everyone-noticed-i-zoned-out-mind-reading-sheet', 'Everyone Noticed I Zoned Out Mind Reading Sheet', 'cbt'::resource_kind, 'A sheet for the moment a client realizes their attention drifted in a conversation and concludes everyone saw and judged it.', 'Use it to help a client separate the fact of a drift from the mind reading that follows and makes rejoining harder.', array['Adults', 'Teens']::text[], '10 minutes after the moment', 'Attention drifts, and the client comes back to find themselves mid-sentence with no idea what was said. The sheet captures that moment: how long the drift probably was, what the client assumes others saw and thought, the evidence for that, the ordinary explanations for the others'' faces, and a rejoining line that is honest and short, such as sorry, say that last part again. The record is less about the drift than about the shame spiral that keeps the client silent for the rest of the conversation. Watch for a client who stays quiet to avoid drifting again; the rejoining line is the homework.', '[{"id": "f0", "type": "textarea", "label": "The conversation, and roughly how long my attention was gone:"}, {"id": "f1", "type": "textarea", "label": "What I assumed everyone saw and thought when I came back:"}, {"id": "f2", "type": "textarea", "label": "Evidence a camera would show, and evidence against the assumption:"}, {"id": "f3", "type": "textarea", "label": "What the others might have been thinking that had nothing to do with me:"}, {"id": "f4", "type": "textarea", "label": "The short, honest line I can use to rejoin next time:"}, {"id": "f5", "type": "textarea", "label": "What I did for the rest of the conversation, and what I would do differently:"}]'::jsonb, array['ADHD', 'thinking traps', 'core CBT', 'attention']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('half-read-books-stack-values-page', 'Half-Read Books Stack Values Page', 'act'::resource_kind, 'A values page that uses the stack of half-read books as a map of what pulled the client in and what they actually want to finish.', 'Use it to help a client with scattered attention choose by values instead of feeling only the shame of unfinished things.', array['Adults', 'Teens']::text[], '20 minutes', 'The stack of half-read books by the bed is usually met with shame. This page treats it as data. The client lists each book, what drew them to it, the page they stopped on and what was happening in their life at the time. Then they sort: finish because it matters, return to the library because it was an impulse, or keep on the shelf because owning it is enough. The sort is by values, not by guilt. Finish with one book and the twenty minutes a week it gets. Watch for a client who commits to finishing all of them; one is the whole assignment.', '[{"id": "f0", "type": "textarea", "label": "Every half-read book in the stack, and what drew me to each one:"}, {"id": "f1", "type": "textarea", "label": "Where I stopped in each, and what was going on in my life then:"}, {"id": "f2", "type": "textarea", "label": "Which ones matter enough to finish, and what value they connect to:"}, {"id": "f3", "type": "textarea", "label": "Which ones were an impulse I can let go without finishing:"}, {"id": "f4", "type": "textarea", "label": "The one book I will give twenty minutes a week, and when:"}, {"id": "f5", "type": "textarea", "label": "What my mind says about the stack, and what the sort says instead:"}]'::jsonb, array['ADHD', 'values', 'core ACT', 'attention']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-starting-three-projects-at-once-grid', 'Pros and Cons of Starting Three Projects at Once Grid', 'dbt'::resource_kind, 'A DBT pros and cons grid for when three new projects all feel urgent, weighing starting all of them against picking one.', 'Use it to give a client a way to pause the thrill of starting and see what three simultaneous starts have cost before.', array['Adults', 'Teens']::text[], '15 minutes when the urge to start hits', 'The urge to start several things at once is exciting, and the grid honors that; the pros of starting go in first. Then the cons, then the pros and cons of picking one and parking the others on a list with a date, each split into short term and long term. The client reads the grid aloud and chooses. Past evidence belongs in the cons column: what happened the last three times. Keep the parked list visible so the other projects feel saved, not killed. Watch for a client who fills the grid and then starts all three anyway; that is useful information for the next session, not a failure.', '[{"id": "f0", "type": "textarea", "label": "The three projects, and why each feels urgent right now:"}, {"id": "f1", "type": "textarea", "label": "Pros of starting all three today: short term, and long term:"}, {"id": "f2", "type": "textarea", "label": "Cons of starting all three today, including what happened the last times:"}, {"id": "f3", "type": "textarea", "label": "Pros of picking one and parking the others with a date:"}, {"id": "f4", "type": "textarea", "label": "Cons of picking one and parking the others:"}, {"id": "f5", "type": "textarea", "label": "My choice, the parked list with dates, and when I will check back on this grid:"}]'::jsonb, array['ADHD', 'pros and cons', 'decisions', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('backpack-pocket-map-craft', 'Backpack Pocket Map Craft', 'kids'::resource_kind, 'A child draws a map of their backpack with a home for each item and tapes it inside the flap, with a one-minute check each evening.', 'Use it to help a child who loses things daily build a visual system for the backpack they are the author of.', array['Children']::text[], '30 minutes to make, one minute a night', 'A lost lunchbox or folder every day wears on a child and a parent. The craft puts the child in charge of the system. Together they empty the backpack, decide which pocket is home for each thing, and the child draws the map: a pocket shape for each compartment with pictures of what lives there. Decorate, laminate with tape, and attach inside the flap. Each evening the parent asks the child to check the map, not the parent to check the bag. Watch for a parent who draws the map themselves; the child''s drawing, however rough, is what makes them use it.', '[{"id": "f0", "type": "textarea", "label": "Draw your backpack with all its pockets:"}, {"id": "f1", "type": "textarea", "label": "Which thing lives in which pocket? Draw it in its home:"}, {"id": "f2", "type": "textarea", "label": "Decorate your map and give it a title:"}, {"id": "f3", "type": "textarea", "label": "The one-minute check each night: what do you look at first?"}, {"id": "f4", "type": "textarea", "label": "Grown-up: how I let my child draw and decide, even when I would have chosen differently:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: how many things came home this week, compared with before the map:"}]'::jsonb, array['ADHD', 'children', 'craft', 'executive function']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('game-day-watch-party-substance-free-plan-sheet', 'Game Day Watch Party Substance-Free Plan Sheet', 'worksheet'::resource_kind, 'A plan for a watch party or sports bar afternoon with substance use all around: the drink in hand, the exit, the ally and the ride home.', 'Use it to help a client get through a sports event where substance use is the default without an unplanned slip.', array['Adults']::text[], '15 minutes before the event', 'Sports events bundle several urge triggers: a crowd, a ritual, a long afternoon, and friends who assume. The sheet plans the details: what will be in the client''s hand from the first minute, who at the gathering knows and will run interference, the answer to want one, the moment they will leave regardless of the score, and how they get home. It also asks what they will do with the urge when the team scores or loses, since both are triggers. Review afterward what the urges were and what held. Watch for a plan with no exit time; overtime is not a reason to stay.', '[{"id": "f0", "type": "textarea", "label": "The event, where it is, and roughly how many hours it runs:"}, {"id": "f1", "type": "textarea", "label": "What is in my hand from the first minute, and how I keep it full:"}, {"id": "f2", "type": "textarea", "label": "Who there knows, and what I have asked them to do:"}, {"id": "f3", "type": "textarea", "label": "My answer when someone offers, in one sentence:"}, {"id": "f4", "type": "textarea", "label": "The time I leave regardless of the score, and how I get home:"}, {"id": "f5", "type": "textarea", "label": "What I do with the urge when the team scores or loses:"}]'::jsonb, array['addiction', 'substance use', 'urges', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('other-people-can-stop-at-one-comparison-sheet', 'Other People Can Stop at One Comparison Sheet', 'cbt'::resource_kind, 'A sheet for the thought that everyone else can stop at one, checking what the client actually knows about other people against assumptions.', 'Use it to help a client see the comparison trap that makes their own situation feel like a personal failure.', array['Adults']::text[], '15 minutes', 'Everyone else can stop at one is a comparison that feels like fact and functions as a reason. The sheet asks the client to name the specific people they are comparing themselves to, what they actually know about each person''s use versus what they assume, who in their life does not fit the picture, and what the comparison does to their motivation on a hard evening. Then a more accurate thought. The goal is to notice how little is known. Watch for the sheet turning into counting other people''s drinks; the attention goes back to the client''s own plan.', '[{"id": "f0", "type": "textarea", "label": "The thought as it shows up, and when it tends to arrive:"}, {"id": "f1", "type": "textarea", "label": "The specific people I am comparing myself to:"}, {"id": "f2", "type": "textarea", "label": "What I actually know about each person''s substance use, and what I am assuming:"}, {"id": "f3", "type": "textarea", "label": "People in my life who do not fit the picture of everyone else:"}, {"id": "f4", "type": "textarea", "label": "What this comparison does to me on a hard evening:"}, {"id": "f5", "type": "textarea", "label": "A more accurate thought, and what I will do with the evening instead:"}]'::jsonb, array['addiction', 'substance use', 'thinking traps', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('minds-highlight-reel-that-cuts-the-morning-after-page', 'Mind''s Highlight Reel That Cuts the Morning After Page', 'act'::resource_kind, 'A defusion page noticing how the mind replays substance use as a highlight reel with the morning after cut, and adds the footage back.', 'Use it to help a client see euphoric recall as editing rather than memory and respond to the reel as a viewer.', array['Adults']::text[], '15 minutes', 'When an urge builds, the mind plays a highlight reel: the laugh, the first warm minute, the relief. The footage from the next morning is never in it. The page has the client describe the reel their mind plays, then write the scenes that were cut: the morning, the texts, the money, the look on someone''s face. The practice is to notice the reel starting and say, here comes the highlight reel, and remember the full cut exists. Watch for a client who only writes punishment in the cut scenes; include what the morning actually felt like.', '[{"id": "f0", "type": "textarea", "label": "The highlight reel my mind plays when an urge builds, scene by scene:"}, {"id": "f1", "type": "textarea", "label": "The scenes that were cut: the morning after, in honest detail:"}, {"id": "f2", "type": "textarea", "label": "What the reel leaves out about how I felt by noon:"}, {"id": "f3", "type": "textarea", "label": "The line I will say when I notice the reel start:"}, {"id": "f4", "type": "textarea", "label": "What I noticed the first time I watched the reel as an edited clip:"}, {"id": "f5", "type": "textarea", "label": "What I want to do with the hour after the reel plays:"}]'::jsonb, array['addiction', 'substance use', 'defusion', 'urges']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-i-can-handle-just-one-card', 'Check the Facts on I Can Handle Just One Card', 'dbt'::resource_kind, 'A Check the Facts card for the thought I can handle just one, run against the client''s own history rather than their hopes.', 'Use it to give a client a DBT fact check for the single most common thought before a slip.', array['Adults']::text[], 'Five minutes when the thought arrives', 'I can handle just one arrives as a calm, reasonable thought, which is what makes it dangerous. The card runs Check the Facts on it: the emotion underneath, the event that prompted it, the interpretation, and then the facts, which here means the last five times the client had just one and what happened by the end of the night. If the facts fit the thought, that is useful to know; if they do not, the card asks what skill fits instead. Fill the history column in session so it is ready before the thought arrives. Watch for a client who edits the history; the number of times is the fact.', '[{"id": "f0", "type": "textarea", "label": "The thought, and the emotion underneath it right now with its intensity:"}, {"id": "f1", "type": "textarea", "label": "What prompted it: where I am, who I am with, what just happened:"}, {"id": "f2", "type": "textarea", "label": "The last five times I had just one: what happened by the end of each night?"}, {"id": "f3", "type": "textarea", "label": "Does the thought fit those facts? What thought would?"}, {"id": "f4", "type": "textarea", "label": "The skill I will use in the next ten minutes instead:"}, {"id": "f5", "type": "textarea", "label": "Who I will tell that the thought showed up today:"}]'::jsonb, array['addiction', 'substance use', 'check the facts', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('money-and-substance-use-transparency-agreement-for-partners', 'Money and Substance Use Transparency Agreement for Partners', 'couples'::resource_kind, 'An agreement on how money and substance use stay visible between partners in early recovery, with the recovering partner setting the terms.', 'Use it to help a couple agree on what transparency means before it becomes surveillance or secrecy.', array['Couples']::text[], 'Full session', 'The agreement has the partner in recovery write what they are willing to make visible, which accounts, what cash, for how long, and what would feel like being policed; the other partner writes what they need to see to sleep at night and what they will do with a worrying number instead of an ambush. Together they set a weekly moment to look at it together, a review date for loosening the terms, and what happens if a slip shows up in the numbers. Watch for an agreement the non-recovering partner wrote alone; the recovering partner sets most of the terms.', '[{"id": "f0", "type": "textarea", "label": "Partner in recovery: what I am willing to make visible, which accounts and what cash, and for how long:"}, {"id": "f1", "type": "textarea", "label": "Partner in recovery: what would feel like being policed, and what I need in return:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I need to be able to see to feel steady, and why:"}, {"id": "f3", "type": "textarea", "label": "Other partner: what I will do with a worrying number instead of an ambush:"}, {"id": "f4", "type": "textarea", "label": "Our weekly moment to look together, and the date we revisit the terms:"}, {"id": "f5", "type": "textarea", "label": "What happens if a slip shows in the numbers, agreed now while we are calm:"}]'::jsonb, array['addiction', 'couples', 'substance use', 'money']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('self-checkout-machine-error-temper-log-sheet', 'Self-Checkout Machine Error Temper Log Sheet', 'worksheet'::resource_kind, 'A log of small machine frustrations tracking the flash of temper, the first body sign, what the client did and how long it lasted.', 'Use it to help a client see the pattern in low-stakes technology anger before it shows up at home.', array['Adults', 'Teens']::text[], 'Two minutes per incident for a week', 'Machines are a safe place to study temper: nobody is hurt, and the pattern is pure. The log records each small tech frustration for a week: the machine, the error, the first body sign, the temper from 0 to 10, what the client did or said, how long the heat lasted, and what was going on before it. Review in session for the pattern: time of day, hunger, what else was pending. The point is to catch the early body sign while the stakes are a grocery bag. Watch for a client who dismisses machine anger as not real anger; the body does not know the difference.', '[{"id": "f0", "type": "textarea", "label": "The machine and the error, in one line:"}, {"id": "f1", "type": "textarea", "label": "The first body sign that I was getting angry:"}, {"id": "f2", "type": "textarea", "label": "My temper from 0 to 10, and what I did or said:"}, {"id": "f3", "type": "textarea", "label": "How long the heat lasted, and what brought it down:"}, {"id": "f4", "type": "textarea", "label": "What was going on before: hunger, time, what else was pending:"}, {"id": "f5", "type": "textarea", "label": "What I notice across the week about when machines get to me:"}]'::jsonb, array['anger management', 'triggers', 'self-monitoring']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('slow-walker-in-the-hallway-should-statement-sheet', 'Slow Walker in the Hallway Should Statement Sheet', 'cbt'::resource_kind, 'A sheet for the should statements that fire at slow walkers and long orders, swapping each rule about strangers for a preference.', 'Use it to help a client catch the rules about how strangers ought to behave that heat an ordinary minute.', array['Adults', 'Teens']::text[], '10 minutes', 'A lot of daily anger is should statements about strangers: they should walk faster, they should know how to order, they should move. The sheet collects a day''s worth of them in the client''s exact words, then for each asks whose rule it is, what happens in the body when the rule is broken, and a rewrite as a preference: I would prefer this to move faster. Preferences can be disappointed without a fire. Finish with the one should that showed up most and its origin. Watch for a client who rewrites and then adds but they still should; the rewrite stands on its own.', '[{"id": "f0", "type": "textarea", "label": "Today''s should statements about strangers, in the exact words my mind used:"}, {"id": "f1", "type": "textarea", "label": "For each: whose rule is it, and where did I learn it?"}, {"id": "f2", "type": "textarea", "label": "What my body does in the moment the rule gets broken:"}, {"id": "f3", "type": "textarea", "label": "Each should rewritten as a preference, without a but:"}, {"id": "f4", "type": "textarea", "label": "The should that showed up most this week, and what it is really about:"}, {"id": "f5", "type": "textarea", "label": "What a preference feels like in the body compared with a rule:"}]'::jsonb, array['anger management', 'thinking traps', 'core CBT', 'should statements']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('carrying-the-grudge-suitcase-page', 'Carrying the Grudge Suitcase Page', 'act'::resource_kind, 'A workability page picturing each grudge as a packed suitcase carried everywhere, weighing the cost of carrying and of setting one down.', 'Use it to help a client examine the workability of a long-held grudge without being told to forgive.', array['Adults', 'Teens']::text[], '20 minutes', 'A grudge is often experienced as justice, and the page does not argue with that. It pictures each grudge as a suitcase: what is in it, how heavy, how long carried, and where it has gone with the client, into bed, to dinner, on vacation. Then the workability question: what does carrying it get, and what does it cost in attention and closeness. Putting a suitcase down is not forgiving anyone; it is choosing where the hands go. The client picks one suitcase to set down for a day and reports. Watch for a client who hears forgiveness anyway; repeat that the suitcase is theirs to pick back up.', '[{"id": "f0", "type": "textarea", "label": "My suitcases: who or what each grudge is about, and how long I have carried it:"}, {"id": "f1", "type": "textarea", "label": "What is packed in the heaviest one:"}, {"id": "f2", "type": "textarea", "label": "Where the heaviest one has gone with me this month:"}, {"id": "f3", "type": "textarea", "label": "What carrying it gets me, honestly, and what it costs:"}, {"id": "f4", "type": "textarea", "label": "One suitcase I am willing to set down for a day, and what my hands would do instead:"}, {"id": "f5", "type": "textarea", "label": "What happened on that day, and whether I picked it back up:"}]'::jsonb, array['anger management', 'willingness', 'workability', 'metaphor']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-slamming-the-door-card', 'Opposite Action to Slamming the Door Card', 'dbt'::resource_kind, 'An opposite action card for the urge to slam, stomp or storm out, with a gentle body and a soft exit the client rehearses in advance.', 'Use it to give a client a specific physical alternative to the slam when anger does not fit the facts or acting on it would not work.', array['Adults', 'Teens']::text[], 'Five minutes to plan, used in the moment', 'Slamming a door discharges something, and it also teaches everyone in the house to brace. The card walks opposite action for the slam: check whether the anger fits the facts and whether slamming would be effective, then the opposite: unclench the jaw and hands, lower the shoulders, speak one quiet sentence about needing a minute, and close the door slowly enough to hear the latch. All the way, including the face. The client rehearses it in a calm moment, with the actual door. Watch for a client who does the slow door with a slammed face; the opposite action includes the expression.', '[{"id": "f0", "type": "textarea", "label": "When the urge to slam or storm out shows up, and what it usually gets me:"}, {"id": "f1", "type": "textarea", "label": "The check: does the anger fit the facts, and would slamming work for what I want?"}, {"id": "f2", "type": "textarea", "label": "The opposite action in order: hands, jaw, shoulders, the one sentence, the slow latch:"}, {"id": "f3", "type": "textarea", "label": "My one quiet sentence about needing a minute:"}, {"id": "f4", "type": "textarea", "label": "What I do during the minute behind the slowly closed door:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the other person did, compared with what happens after a slam:"}]'::jsonb, array['anger management', 'opposite action', 'de-escalation', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('anger-cue-charades-spot-the-early-sign-game', 'Anger Cue Charades Spot the Early Sign Game', 'game'::resource_kind, 'Players act out the first body signs of rising anger and the group names the sign and a next move, getting fluent at early cues.', 'Use it to help a group get fluent at spotting early anger cues in themselves and each other before the explosion.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: slips name early anger signs: jaw tightens, fists clench, voice drops, breath goes short, heat in the face, pacing, going silent. A player draws one and acts it in slow motion while the group guesses the sign within a minute. Once named, the group has thirty seconds to shout one thing that player could do next: walk, breathe, say I need a minute. Debrief: which sign each person recognized as their own, which they had never noticed, and which next move they would actually use. Watch for players acting the explosion rather than the cue; redirect to the earliest sign.', '[{"id": "f0", "type": "textarea", "label": "The signs I acted or guessed, and the one I recognized as mine:"}, {"id": "f1", "type": "textarea", "label": "A sign I had never noticed in myself until today:"}, {"id": "f2", "type": "textarea", "label": "The next moves the group shouted that I would actually use:"}, {"id": "f3", "type": "textarea", "label": "Someone who knows me well: which sign would they say shows first?"}, {"id": "f4", "type": "textarea", "label": "What it was like to act anger slowly instead of fast:"}, {"id": "f5", "type": "textarea", "label": "My earliest sign, and the move that goes with it, in one line:"}]'::jsonb, array['anger management', 'game', 'triggers', 'group']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('asking-the-same-question-twice-family-tally-sheet', 'Asking the Same Question Twice Family Tally Sheet', 'worksheet'::resource_kind, 'A tally a client and a family member keep of repeated questions asked for certainty, with an agreed kind answer for the second time.', 'Use it to help a client and their family see how much reassurance is being asked and give the family one kind script.', array['Adults', 'Teens']::text[], 'One week, 30 seconds per tally', 'Repeated questions are reassurance seeking wearing ordinary clothes: did I lock it, are you sure, did that sound okay. The sheet is kept by both the client and one family member for a week: each repeated question, what it was about, what the family member said, and how long the relief lasted. Together with the clinician they agree on a kind second-time answer, such as I love you and we agreed I would not answer that twice. The family member''s job is the script, not the monitoring. Watch for the sheet becoming a scoreboard against the client; both columns are data for the room.', '[{"id": "f0", "type": "textarea", "label": "The questions I ask more than once, grouped by what they are about:"}, {"id": "f1", "type": "textarea", "label": "Family member: the repeated questions I was asked this week, and what I usually say:"}, {"id": "f2", "type": "textarea", "label": "How long the relief lasts after an answer, in minutes or hours:"}, {"id": "f3", "type": "textarea", "label": "The kind second-time answer we agreed on, word for word:"}, {"id": "f4", "type": "textarea", "label": "What I did with the urge when the answer did not come:"}, {"id": "f5", "type": "textarea", "label": "Both of us: what changed in the house this week, and what was hard about it:"}]'::jsonb, array['OCD', 'rituals', 'family', 'intrusive thoughts']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('mismatched-socks-all-day-prediction-sheet', 'Mismatched Socks All Day Prediction Sheet', 'cbt'::resource_kind, 'An experiment predicting how unbearable the not-just-right feeling of mismatched socks will be across a day, tracked hourly.', 'Use it to help a client test their prediction about how long a not-just-right feeling lasts when nothing is done about it.', array['Adults', 'Teens']::text[], 'One day, one minute an hour', 'Clients who need things to feel just right often predict the feeling will stay at full volume until fixed. Mismatched socks are a small, private test. The client predicts the discomfort at each hour of the day and how sure they are it will not drop, then wears the socks and rates the actual discomfort hourly without fixing anything. Compare the two curves in session. Most clients find the feeling moves on its own. Pick a different small mismatch if socks are not the client''s thing. Watch for a client who fixes it at noon and reports success; the sheet is about the curve, not the endurance.', '[{"id": "f0", "type": "textarea", "label": "The mismatch I will wear or leave, and what the not-just-right feeling says will happen:"}, {"id": "f1", "type": "textarea", "label": "My predicted discomfort for each hour of the day, 0 to 100, and how sure I am it will not drop:"}, {"id": "f2", "type": "textarea", "label": "My actual discomfort each hour, without fixing anything:"}, {"id": "f3", "type": "textarea", "label": "The hour the feeling first dropped, and what I was doing:"}, {"id": "f4", "type": "textarea", "label": "Urges to fix it, and what I did with them:"}, {"id": "f5", "type": "textarea", "label": "What the two curves tell me about how long the feeling needs me:"}]'::jsonb, array['OCD', 'predictions', 'exposure', 'behavioral experiment']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('doubt-as-a-telemarketer-who-keeps-calling-page', 'Doubt as a Telemarketer Who Keeps Calling Page', 'act'::resource_kind, 'A defusion page that treats doubt as a telemarketer who keeps calling, so the client can let it ring instead of picking up to argue.', 'Use it to help a client stop engaging with doubt as if answering it would end the calls.', array['Adults', 'Teens']::text[], '15 minutes', 'Doubt calls constantly: are you sure, what if, check again. Every time the client picks up and argues, the number gets marked as responsive. The page writes out a typical call, what the telemarketer says and how the client usually answers, then the new practice: let it ring, say there is the doubt line again, and continue what they were doing. Hanging up is not the goal; not picking up is. The client logs the calls for a few days and what happened when they did not answer. Watch for a client who screens calls by checking once to be sure; checking is picking up.', '[{"id": "f0", "type": "textarea", "label": "A typical doubt call: what it says, and how I usually answer it:"}, {"id": "f1", "type": "textarea", "label": "How many calls on an ordinary day, and the hours they cluster:"}, {"id": "f2", "type": "textarea", "label": "What answering has gotten me, and what it has cost:"}, {"id": "f3", "type": "textarea", "label": "My line when I notice a call: there is the doubt line again, and then what I keep doing:"}, {"id": "f4", "type": "textarea", "label": "Calls I let ring this week, and what happened next:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the calls once I stopped picking up:"}]'::jsonb, array['OCD', 'defusion', 'uncertainty', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-away-from-the-mental-checklist-card', 'Turning the Mind Away From the Mental Checklist Card', 'dbt'::resource_kind, 'A Turning the Mind card for the moment a mental checklist or review begins, choosing again and again to turn back to the present task.', 'Use it to give a client a DBT move for mental rituals that cannot be interrupted by stopping a hand.', array['Adults', 'Teens']::text[], 'One minute, many times a day', 'Mental rituals are harder than physical ones because there is nothing to put down. Turning the Mind is the fit: the client notices the mental checklist or review has begun, acknowledges it, and makes an inner turn back to what their hands and eyes are doing, as many times as needed, without finishing the list. The card asks what the turn feels like, what cue tells them the list has started, and a short phrase for the turn. Expect many turns an hour at first. Watch for a client who turns by finishing the list quickly first; the turn happens mid-list.', '[{"id": "f0", "type": "textarea", "label": "The mental checklist or review I run, described in general terms:"}, {"id": "f1", "type": "textarea", "label": "The cue that tells me it has started: a body feeling, a word, a pull:"}, {"id": "f2", "type": "textarea", "label": "My phrase for the turn, and what my hands and eyes return to:"}, {"id": "f3", "type": "textarea", "label": "How many turns in a typical hour this week, roughly:"}, {"id": "f4", "type": "textarea", "label": "What the unfinished list did when I did not go back to it:"}, {"id": "f5", "type": "textarea", "label": "What got easier or harder across the week:"}]'::jsonb, array['OCD', 'turning the mind', 'core DBT', 'rituals']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('bossy-brain-rule-breaking-bingo-craft', 'Bossy Brain Rule Breaking Bingo Craft', 'kids'::resource_kind, 'A child draws a bingo card of small bossy brain rules to break and colors in a square each time they break one, with a parent cheering.', 'Use it to help a child who follows rigid self-made rules practice breaking small ones in a game they designed.', array['Children']::text[], '30 minutes to make, used for two weeks', 'Children with a bossy brain follow rules it makes: the cup has to be blue, the shoes go in this order, the door must be closed twice. The craft turns rule breaking into bingo. The child and parent list the small rules together, the child picks nine or sixteen they are willing to break, draws each in a square and decorates the card. Each break earns a colored square, and a line earns a chosen celebration. The parent cheers the break and does not fix the result. Keep the first rules very small. Watch for a parent who adds the hardest rules to the card; the child chooses.', '[{"id": "f0", "type": "textarea", "label": "My bossy brain rules, the ones I am willing to break, drawn in bingo squares:"}, {"id": "f1", "type": "textarea", "label": "The easiest square to start with, and when I will do it:"}, {"id": "f2", "type": "textarea", "label": "Color a square each time: what did the bossy brain say when you broke the rule?"}, {"id": "f3", "type": "textarea", "label": "What happened after, and how long until the bossy feeling got smaller:"}, {"id": "f4", "type": "textarea", "label": "The celebration for a line, chosen by me:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: how I cheered the break and left the cup where it was:"}]'::jsonb, array['OCD', 'children', 'craft', 'exposure']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('car-wash-tunnel-trapped-minute-plan-sheet', 'Car Wash Tunnel Trapped Minute Plan Sheet', 'worksheet'::resource_kind, 'A plan for the automatic car wash, a short enclosed minute many clients with panic avoid, with the sensations expected and moves rehearsed.', 'Use it to help a client approach a brief, contained trapped feeling on purpose with a plan they can repeat.', array['Adults', 'Teens']::text[], '10 minutes to plan, one car wash', 'An automatic car wash is a near-perfect practice ground: enclosed, noisy, dark, and over in a few minutes with no way to stop it early. The sheet has the client predict the sensations, rate the expected peak, plan what they will do with their hands and attention, and decide what they will not do: no phone, no gripping the wheel, no eyes shut. Afterward they rate the actual peak and how long it lasted. Repeat weekly if useful, varying the time of day. Watch for a client who brings a passenger to talk them through it; the second run is alone.', '[{"id": "f0", "type": "textarea", "label": "The car wash I will use, and when:"}, {"id": "f1", "type": "textarea", "label": "The sensations I expect, and the peak I predict from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What I will do with my hands and my attention during the tunnel:"}, {"id": "f3", "type": "textarea", "label": "What I will not do: the safety moves I am leaving in the glove box:"}, {"id": "f4", "type": "textarea", "label": "The actual peak, and how long it took to come down after the dryer:"}, {"id": "f5", "type": "textarea", "label": "What surprised me, and when I will go again:"}]'::jsonb, array['panic attacks', 'exposure', 'avoidance', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('i-will-lose-control-and-scream-prediction-sheet', 'I Will Lose Control and Scream Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the fear of losing control in public during a surge, checking how many surges have ended in the predicted scene.', 'Use it to help a client test the belief that panic will make them do something out of control.', array['Adults', 'Teens']::text[], '15 minutes', 'Many clients fear not the sensations but what they will do: scream, run, collapse, make a scene. The sheet writes the exact feared scene, then counts: how many surges in the client''s life, how many ended in that scene, what they actually did each time. The numbers are usually dozens to zero. Then the sheet asks what the fear is really about, often being seen, and what the client would do if the scene happened anyway. Rerate the belief. Watch for a client who credits escaping for the zero; list the surges where escape was impossible, on a plane or in a chair.', '[{"id": "f0", "type": "textarea", "label": "The scene I am afraid of, exactly: what I would do and who would see:"}, {"id": "f1", "type": "textarea", "label": "Roughly how many surges I have had in my life:"}, {"id": "f2", "type": "textarea", "label": "How many ended in that scene, and what I actually did in the others:"}, {"id": "f3", "type": "textarea", "label": "Surges where I could not leave, and what happened:"}, {"id": "f4", "type": "textarea", "label": "What this fear is really about underneath the scene:"}, {"id": "f5", "type": "textarea", "label": "My belief in the prediction before and after, from 0 to 100:"}]'::jsonb, array['panic attacks', 'predictions', 'panic', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('panic-on-the-guest-list-not-the-host-page', 'Panic on the Guest List Not the Host Page', 'act'::resource_kind, 'An acceptance page that puts panic on the guest list for an event the client wants to attend, as one guest rather than the host.', 'Use it to help a client attend something that matters with panic invited rather than in charge.', array['Adults', 'Teens']::text[], '15 minutes before an event', 'Avoidance treats panic as the host: if it might come, the event is off. This page makes it a guest. The client names an upcoming event they want to be at, lists the guests they care about, and adds panic to the list with a seat, a plus one of sensations, and no job. They write what the other guests mean to them and what they would miss by staying home. Afterward, whether panic showed, where it sat and how long it stayed. Watch for a client who plans to leave the moment the guest arrives; a guest can be in the room while the client talks to someone else.', '[{"id": "f0", "type": "textarea", "label": "The event I want to be at, and who matters to me there:"}, {"id": "f1", "type": "textarea", "label": "Panic on the guest list: its seat, its plus one of sensations, and its job, which is none:"}, {"id": "f2", "type": "textarea", "label": "What I would miss by staying home:"}, {"id": "f3", "type": "textarea", "label": "What I will do when the guest arrives: who I talk to, what my feet do:"}, {"id": "f4", "type": "textarea", "label": "Did panic come? Where did it sit, and how long did it stay?"}, {"id": "f5", "type": "textarea", "label": "What hosting the event myself felt like:"}]'::jsonb, array['panic attacks', 'acceptance', 'willingness', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('observe-the-sweaty-palms-without-wiping-card', 'Observe the Sweaty Palms Without Wiping Card', 'dbt'::resource_kind, 'An Observe skill card for a single panic sensation, damp palms, noticed and described for one minute without wiping, hiding or explaining.', 'Use it to give a client one small mindfulness practice that shrinks a sensation by attending to it instead of fixing it.', array['Adults', 'Teens']::text[], 'One minute, several times a week', 'Sweaty palms are one of the sensations clients most want to hide, which keeps the hands busy and the fear alive. The card uses Observe: hands resting open on the knees, attention on the palms, describing only sensations, damp, cool, tingling, for one minute, with every urge to wipe or hide noted and let pass. No judgment words. Afterward the client notes what the sensation did under attention. Practice first when calm, then during mild nerves. Watch for a client who observes and then wipes at the bell; the hands stay open for another breath.', '[{"id": "f0", "type": "textarea", "label": "When my palms get damp, and what I normally do within seconds:"}, {"id": "f1", "type": "textarea", "label": "One minute of observing: the sensations in plain words, no judgments:"}, {"id": "f2", "type": "textarea", "label": "Urges that showed up during the minute, and what I did with them:"}, {"id": "f3", "type": "textarea", "label": "What the sensation did under attention: stayed, moved, faded, grew:"}, {"id": "f4", "type": "textarea", "label": "Practice this week: when I did it, and what my nerves were doing:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about my hands when I stopped managing them:"}]'::jsonb, array['panic attacks', 'mindfulness', 'body awareness', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('grocery-store-panic-hand-signal-plan-for-partners', 'Grocery Store Panic Hand Signal Plan for Partners', 'couples'::resource_kind, 'A plan for partners shopping together when one has panic, with a hand signal, a regroup spot and an agreement to stay rather than run.', 'Use it to help a couple handle a surge in a public place without a scene, a rescue or a fight in the parking lot.', array['Couples']::text[], '15 minutes before the next shop', 'A surge in a store usually produces either a rescue, where the partner abandons the cart and gets them out, or a standoff. The plan does better. The partner with panic writes the signal that means a surge is starting, what they want from their partner in the first minute, and what they want not to hear; the other partner writes what they will do, where they will stand, and what they will say. Together they agree on a bench or aisle to regroup in and a rule to finish the shop, even slowly. Watch for a plan where the other partner does the surviving for them; their job is presence, not rescue.', '[{"id": "f0", "type": "textarea", "label": "Partner with panic: my signal that a surge is starting, and what I want from you in the first minute:"}, {"id": "f1", "type": "textarea", "label": "Partner with panic: what I do not want to hear, however kind:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I will do, where I will stand, and the one thing I will say:"}, {"id": "f3", "type": "textarea", "label": "Other partner: what is hard for me in those minutes, honestly:"}, {"id": "f4", "type": "textarea", "label": "Our regroup spot in the store, and our rule about finishing the shop:"}, {"id": "f5", "type": "textarea", "label": "After: what happened, what helped, and what we change next time:"}]'::jsonb, array['panic attacks', 'couples', 'planning', 'support']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('after-school-meltdown-snack-and-space-plan-sheet', 'After School Meltdown Snack and Space Plan Sheet', 'worksheet'::resource_kind, 'A plan for the hour after school when a held-together child falls apart: snack ready, questions saved and space set before the door opens.', 'Use it to help a parent stop meeting the after-school meltdown with questions and start meeting it with food and quiet.', array['Adults']::text[], '15 minutes to plan, used daily', 'Many children hold it together all day and spend the first hour home falling apart on the safest person they have. Parents often meet that hour with how was school and get a slammed door. The sheet plans the hour: what snack is out before the door opens, where the quiet space is, which questions wait until dinner, what the parent does with their own need to connect, and a signal the child can give that means not yet. Review after a week what the hour looked like. Watch for a parent who hears the plan as letting the child be rude; the plan is about timing, not standards.', '[{"id": "f0", "type": "textarea", "label": "What the first hour after school usually looks like now, honestly:"}, {"id": "f1", "type": "textarea", "label": "The snack that will be out before the door opens, and where:"}, {"id": "f2", "type": "textarea", "label": "The quiet space my child can go, and what is in it:"}, {"id": "f3", "type": "textarea", "label": "The questions I will save for dinner, and the one thing I will say at the door instead:"}, {"id": "f4", "type": "textarea", "label": "What I will do with my own wish to connect in that hour:"}, {"id": "f5", "type": "textarea", "label": "After a week: what the hour looked like, and what dinner was like:"}]'::jsonb, array['parenting', 'routines', 'regulation', 'family']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('other-kids-already-do-this-comparison-check-sheet', 'Other Kids Already Do This Comparison Check Sheet', 'cbt'::resource_kind, 'A sheet for the parent thought that other children already do something theirs cannot, checking the sample size and what is actually known.', 'Use it to help a parent catch comparison thinking about their child''s pace before it turns into pressure at home.', array['Adults']::text[], '15 minutes', 'Other kids already do this arrives at the playground, in the group chat and at pickup, and it lands on the child as pressure. The sheet asks the parent to name the specific skill, the specific other children, what they actually observed versus heard, how many children they are comparing against, and what they know about those children''s whole picture. Then a more accurate thought, and what their own child did this week that the comparison skipped. Watch for a parent who flips to my child is fine and stops; the sheet ends with a question for the pediatrician or teacher if one is warranted.', '[{"id": "f0", "type": "textarea", "label": "The skill, and the thought in my words:"}, {"id": "f1", "type": "textarea", "label": "The other children I am comparing against, and how many there are:"}, {"id": "f2", "type": "textarea", "label": "What I actually saw with my own eyes, and what I heard secondhand:"}, {"id": "f3", "type": "textarea", "label": "What I know about those children''s whole picture, and what I do not:"}, {"id": "f4", "type": "textarea", "label": "What my child did this week that the comparison skipped:"}, {"id": "f5", "type": "textarea", "label": "A more accurate thought, and any real question I want to bring to the teacher or pediatrician:"}]'::jsonb, array['parenting', 'thinking traps', 'core CBT', 'comparison']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('toddler-tantrum-in-the-parking-lot-values-page', 'Toddler Tantrum in the Parking Lot Values Page', 'act'::resource_kind, 'A values page for the public tantrum, naming the parent the client wants to be in the parking lot when strangers are watching.', 'Use it to help a parent act from their values in the most watched parenting moment instead of from the audience''s imagined verdict.', array['Adults']::text[], '15 minutes', 'The parking lot tantrum has an audience, and the audience often ends up parenting the child. The page asks what the parent did last time, what the strangers'' faces seemed to say, what they would want a parent they admire to do in that lot, and the two values that parent would be acting from. Then the specific moves: where the hands go, what the voice does, what is said to the child and what is said, if anything, to the audience. The next tantrum is the practice. Watch for a parent who writes a calm fantasy; include what to do when they feel the heat rise.', '[{"id": "f0", "type": "textarea", "label": "The last public tantrum: where, what I did, and what the strangers'' faces seemed to say:"}, {"id": "f1", "type": "textarea", "label": "The parent I admire in that lot: what they would do, and the two values they would be acting from:"}, {"id": "f2", "type": "textarea", "label": "Where my hands go, what my voice does, and what I say to my child:"}, {"id": "f3", "type": "textarea", "label": "What I say, if anything, to the audience:"}, {"id": "f4", "type": "textarea", "label": "What I do with the heat in my face when it rises:"}, {"id": "f5", "type": "textarea", "label": "The next time: what happened, and which value I managed to act from:"}]'::jsonb, array['parenting', 'values', 'willingness', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('validation-before-correction-card-for-parents', 'Validation Before Correction Card for Parents', 'dbt'::resource_kind, 'A card for parents to validate what their child feels in one sentence before any correction, drafted for the week''s likely moments.', 'Use it to help a parent make validation the first move so correction lands on a child who feels heard.', array['Adults']::text[], '10 minutes to draft, used daily', 'Correction without validation teaches a child that their feeling was the problem. The card has the parent list the week''s predictable flashpoints, screens off, sibling grabs, bedtime, and draft one validating sentence for each that names the feeling and makes sense of it without agreeing with the behavior: you really wanted more time, and it is hard to stop. Then the correction, short. The order is the practice. The parent tracks which moments they managed it and what the child did next. Watch for validation delivered in a correcting tone; the voice has to match the words.', '[{"id": "f0", "type": "textarea", "label": "This week''s predictable flashpoints with my child:"}, {"id": "f1", "type": "textarea", "label": "For each: one validating sentence that names the feeling and makes sense of it:"}, {"id": "f2", "type": "textarea", "label": "For each: the short correction that follows:"}, {"id": "f3", "type": "textarea", "label": "Moments this week I got the order right, and what my child did next:"}, {"id": "f4", "type": "textarea", "label": "Moments I corrected first, and what happened:"}, {"id": "f5", "type": "textarea", "label": "What my voice needs to do for the validation to count:"}]'::jsonb, array['parenting', 'validation', 'communication', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('family-calm-down-code-word-poster-craft', 'Family Calm Down Code Word Poster Craft', 'kids'::resource_kind, 'A child invents a family code word anyone can say when a moment gets too hot, draws its poster and practices it on the grown-ups too.', 'Use it to give a family one shared signal for pausing that the child authored and can use on the grown-ups too.', array['Children']::text[], '30 minutes to make, practiced weekly', 'Children feel the heat in a house before anyone names it. The craft lets the child choose a silly code word, pineapple, moonbeam, that anyone in the family can say when a moment is getting too hot, and what happens when it is said: everyone stops talking, takes three breaths and sits down. The child draws the poster with the word and the steps, and it goes on the fridge. Then parent and child act a pretend argument about a toy and the child gets to call the word. The parent must obey it too. Watch for a parent who uses the word only on the child; the child using it on the parent is the point.', '[{"id": "f0", "type": "textarea", "label": "Our family code word, and why I picked it:"}, {"id": "f1", "type": "textarea", "label": "What everybody does when someone says it, in three drawn steps:"}, {"id": "f2", "type": "textarea", "label": "Draw the poster: the word, the steps, and where it hangs:"}, {"id": "f3", "type": "textarea", "label": "Practice: I called it during the pretend argument. What did my grown-up do?"}, {"id": "f4", "type": "textarea", "label": "Grown-up: a real moment this week someone used the word, and what happened:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: a time my child used it on me, and how I obeyed it:"}]'::jsonb, array['parenting', 'children', 'craft', 'de-escalation']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('baby-monitor-checking-count-log-sheet', 'Baby Monitor Checking Count Log Sheet', 'worksheet'::resource_kind, 'A log of how often a new parent checks the baby monitor, the thought that sent them and a gentler check interval to try.', 'Use it to help a new parent see the shape of their monitor checking and try a gentler interval without being told not to look.', array['Adults']::text[], 'Three days, a tally mark per check', 'Monitor checking can swallow a new parent''s only rest. The log is a tally: each check during a nap or night, the thought that sent them, the number from 0 to 10 of the fear, and what they saw. After three days they look at the pattern and pick an interval to try, from every few minutes to every fifteen, with what they will do between checks. The log is not about stopping; it is about a parent choosing when to look. Watch for a parent whose fear number never drops after a check; that is worth more time in session than the tally.', '[{"id": "f0", "type": "textarea", "label": "Each check: the time, the thought that sent me, my fear from 0 to 10, and what I saw:"}, {"id": "f1", "type": "textarea", "label": "Across three days: when do the checks cluster?"}, {"id": "f2", "type": "textarea", "label": "How long the relief lasts after a check:"}, {"id": "f3", "type": "textarea", "label": "The interval I will try next, and what I will do with my hands and eyes between checks:"}, {"id": "f4", "type": "textarea", "label": "What happened to the fear number across the trial:"}, {"id": "f5", "type": "textarea", "label": "What I want to tell my clinician about the thoughts that send me to the screen:"}]'::jsonb, array['perinatal and postpartum', 'self-monitoring', 'worry', 'sleep']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('other-new-parents-seem-to-love-it-comparison-sheet', 'Other New Parents Seem to Love It Comparison Sheet', 'cbt'::resource_kind, 'A sheet for the thought that other new parents are enjoying this and the client is not, checking the sources and what they leave out.', 'Use it to help a new parent catch comparison thinking fed by feeds and group chats and find what is true for them.', array['Adults']::text[], '15 minutes', 'The newborn months are now lived next to a feed of other parents who appear to love every minute. The sheet asks where the comparison comes from, pictures, posts, a specific friend, what each source shows and what it cannot show, who the client knows who has said something honest, and what they would say to a friend who confessed to not enjoying it. Then a more accurate thought, and the one honest person to say something to this week. Watch for the sheet becoming a reason to mute everyone; the goal is a truer picture, and one true conversation.', '[{"id": "f0", "type": "textarea", "label": "The thought in my words, and where it tends to arrive:"}, {"id": "f1", "type": "textarea", "label": "The sources: which feeds, posts, friends or relatives feed the comparison:"}, {"id": "f2", "type": "textarea", "label": "What each source shows, and what it cannot show about those parents'' days:"}, {"id": "f3", "type": "textarea", "label": "Anyone who has said something honest to me about the early months:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who told me they were not enjoying this:"}, {"id": "f5", "type": "textarea", "label": "A more accurate thought, and the one honest person I will say something to this week:"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'core CBT', 'comparison']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('advice-from-the-grocery-store-stranger-defusion-page', 'Advice From the Grocery Store Stranger Defusion Page', 'act'::resource_kind, 'A defusion page for the unsolicited advice a new parent collects, sorted by whether each line serves the client''s own values.', 'Use it to help a new parent hold the flood of advice lightly and act from what they and their family actually value.', array['Adults']::text[], '15 minutes', 'A new parent is advised constantly: the stranger in the checkout line, the mother-in-law, the forum at three in the morning. The page collects this week''s advice as a list of quotations, then asks the client to notice each as words from a person with their own history rather than as instructions. The sort: which lines point at something the client values, which are about the speaker, and which can be thanked and set down. Finish with the two or three values the client is actually parenting from. Watch for a client who argues with each line; the practice is to notice and sort, not to win.', '[{"id": "f0", "type": "textarea", "label": "This week''s advice, quoted, and who it came from:"}, {"id": "f1", "type": "textarea", "label": "For each line: what might be going on for the person who said it?"}, {"id": "f2", "type": "textarea", "label": "Lines that point at something I actually value:"}, {"id": "f3", "type": "textarea", "label": "Lines that are about the speaker, and lines I can thank and set down:"}, {"id": "f4", "type": "textarea", "label": "The two or three values I am parenting from, in my words:"}, {"id": "f5", "type": "textarea", "label": "What I will say the next time a stranger offers advice, out loud or inside:"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'values', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('please-skills-in-the-fourth-trimester-card', 'PLEASE Skills in the Fourth Trimester Card', 'dbt'::resource_kind, 'A PLEASE skills card scaled to the months after birth: the body, the meals, the substances, the broken sleep and the movement that fits.', 'Use it to help a new parent reduce emotional vulnerability through the basics, scaled to what a newborn allows.', array['Adults']::text[], 'Two minutes a day for two weeks', 'PLEASE, treating physical illness, balanced eating, avoiding mood-altering substances, balanced sleep and exercise, was not written for someone with a newborn, so the card scales it. For each letter the client writes what is realistically possible this week: the appointment they are overdue for, food they can eat one-handed, what they are using to cope, how sleep can be protected in pieces, and movement that is a walk with the stroller. Each day gets a check for each letter attempted. Watch for a parent who scores themselves on the whole word; one letter a day is a win in this season.', '[{"id": "f0", "type": "textarea", "label": "Physical: the appointment or symptom of my own I have been putting off:"}, {"id": "f1", "type": "textarea", "label": "Eating: what I can realistically eat one-handed this week, and when:"}, {"id": "f2", "type": "textarea", "label": "Substances: what I am using to cope with the days, honestly, and whether it is helping:"}, {"id": "f3", "type": "textarea", "label": "Sleep: how sleep can be protected in pieces, and who can take one piece:"}, {"id": "f4", "type": "textarea", "label": "Exercise: the movement that fits this week, even ten minutes:"}, {"id": "f5", "type": "textarea", "label": "Each day: which letters I attempted, and what I noticed in my mood:"}]'::jsonb, array['perinatal and postpartum', 'PLEASE', 'self-care', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('who-gets-up-tonight-tiebreaker-for-new-parents', 'Who Gets Up Tonight Tiebreaker for New Parents', 'couples'::resource_kind, 'A tiebreaker for the three in the morning moment when both parents are too tired to be fair, decided in daylight with limits written down.', 'Use it to help new parents stop negotiating at three in the morning and follow a rule they made when rested.', array['Couples']::text[], '20 minutes in daylight', 'At three in the morning neither partner can be fair, and who is more tired is the argument they have most often. Each partner writes what their body needs to function tomorrow, what their week looks like, and what resentments the nights have built. Then the tiebreaker: alternating nights, split shifts, a rule for the night before a workday, and the one exception each partner can call without explaining. The rule is followed at night and revisited weekly. Watch for a tiebreaker that is fair on paper and lands on one partner in practice; the weekly review catches that.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need to function tomorrow, and what the nights have built up in me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need to function tomorrow, and what the nights have built up in me:"}, {"id": "f2", "type": "textarea", "label": "Our tiebreaker rule, in one line: who gets up, and how we alternate:"}, {"id": "f3", "type": "textarea", "label": "The exception each of us can call without explaining, and how often:"}, {"id": "f4", "type": "textarea", "label": "What we will say at three in the morning instead of negotiating:"}, {"id": "f5", "type": "textarea", "label": "Weekly review: how the rule landed on each of us, and what we adjust:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'fairness', 'sleep']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('apologizing-for-existing-sorry-count-log-sheet', 'Apologizing for Existing Sorry Count Log Sheet', 'worksheet'::resource_kind, 'A log of every unnecessary sorry in a day, what it was for, who heard it and what a plain sentence would have been instead.', 'Use it to help a client see how often they apologize for taking up space and practice one replacement sentence.', array['Adults', 'Teens']::text[], 'One day, a tally mark per sorry', 'Some clients apologize for asking a question, for existing in a doorway, for having a need. The log tallies a day''s sorries: what each was for, whether anything was actually wrong, who heard it and what a plain sentence would have been, excuse me, thank you, I have a question. Review the total and the pattern in session. Then the client picks one replacement sentence and uses it for a week, tallying both. Watch for a client who apologizes for the number of sorries on the sheet; name it with some lightness, and add it to the tally.', '[{"id": "f0", "type": "textarea", "label": "Each sorry today: what it was for, and who heard it:"}, {"id": "f1", "type": "textarea", "label": "For each: was anything actually wrong?"}, {"id": "f2", "type": "textarea", "label": "The plain sentence that could have gone in its place:"}, {"id": "f3", "type": "textarea", "label": "The total, and the situations where sorries cluster:"}, {"id": "f4", "type": "textarea", "label": "The one replacement sentence I will use this week:"}, {"id": "f5", "type": "textarea", "label": "After a week: how the replacement landed, and what people did:"}]'::jsonb, array['self-esteem', 'self-monitoring', 'assertiveness', 'communication']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('beginner-means-failure-belief-check-sheet', 'Beginner Means Failure Belief Check Sheet', 'cbt'::resource_kind, 'A sheet for the belief that being bad at something new proves inadequacy, checked against every skill the client once did badly.', 'Use it to help a client who avoids new things test the rule that a beginner''s performance is a verdict on them.', array['Adults', 'Teens']::text[], '15 minutes', 'The belief that being a beginner is humiliating keeps clients from trying anything they are not already good at. The sheet states the rule, then asks for five things the client does competently now and what their first attempt at each looked like, what they would say to a friend starting the same thing, and what the rule has cost them in things not tried. Then a rewritten rule and one new thing to be bad at this month, on purpose. Watch for a client who picks a new thing they secretly expect to be good at; the assignment is to be a beginner.', '[{"id": "f0", "type": "textarea", "label": "The rule in my words, and the new thing it is keeping me from:"}, {"id": "f1", "type": "textarea", "label": "Five things I do competently now:"}, {"id": "f2", "type": "textarea", "label": "What my first attempt at each of those actually looked like:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend on their first day at the same thing:"}, {"id": "f4", "type": "textarea", "label": "What this rule has cost me in things not tried:"}, {"id": "f5", "type": "textarea", "label": "The rewritten rule, and the one thing I will be a beginner at this month:"}]'::jsonb, array['self-esteem', 'core beliefs', 'perfectionism', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('values-resume-instead-of-achievements-page', 'Values Resume Instead of Achievements Page', 'act'::resource_kind, 'A page that writes a resume of values lived rather than positions held, listing moments the client acted on what mattered.', 'Use it to help a client whose worth is tied to accomplishment practice describing themselves by what they stand for.', array['Adults', 'Teens']::text[], '20 minutes', 'A client who measures themselves by achievement has a resume that can only shrink. This page writes a different one: the headings are values, honesty, care, courage, curiosity, and under each the client lists moments they acted on it, including the ones that did not work out. A failed business started from courage counts. A hard conversation had with care counts. The client reads it aloud and notices which document feels more like them. Watch for a client who only lists outcomes under the values; ask for the moment they chose the value when the outcome was not yet known.', '[{"id": "f0", "type": "textarea", "label": "The values that would be the headings on my resume, four or five:"}, {"id": "f1", "type": "textarea", "label": "Under each: moments I acted on it, including the ones that did not work out:"}, {"id": "f2", "type": "textarea", "label": "A moment I chose a value before I knew how it would turn out:"}, {"id": "f3", "type": "textarea", "label": "What this resume says about me that my achievements resume does not:"}, {"id": "f4", "type": "textarea", "label": "Which one feels more like me when I read it aloud:"}, {"id": "f5", "type": "textarea", "label": "One entry I could add this month, regardless of how it goes:"}]'::jsonb, array['self-esteem', 'values', 'self-as-context', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('cheerleading-statements-before-the-interview-card', 'Cheerleading Statements Before the Interview Card', 'dbt'::resource_kind, 'A DBT cheerleading statements card for a specific job interview, with the statements written in advance and the self-criticism they answer.', 'Use it to help a client walk into a high-stakes evaluation with statements that steady them instead of the usual self-attack.', array['Adults', 'Teens']::text[], '15 minutes before the interview', 'Cheerleading statements are the interpersonal effectiveness tool for the minutes before a hard encounter. The card ties them to one interview: the client writes the self-critical lines they expect in the waiting room, then a cheerleading statement for each that is true and specific: I have prepared, I am allowed to ask for a moment, a bad answer is not the whole interview. They read the card in the parking lot and once more in the restroom. Afterward they note which statement they actually used. Watch for statements that are grand or untrue; the client needs to believe each one.', '[{"id": "f0", "type": "textarea", "label": "The interview: for what, when, and what I am most afraid of in it:"}, {"id": "f1", "type": "textarea", "label": "The self-critical lines I expect to hear in my head in the waiting room:"}, {"id": "f2", "type": "textarea", "label": "A cheerleading statement for each that is true and specific:"}, {"id": "f3", "type": "textarea", "label": "Where and when I will read the card before I walk in:"}, {"id": "f4", "type": "textarea", "label": "Which statement I actually used, and when:"}, {"id": "f5", "type": "textarea", "label": "What I would add to the card for the next interview:"}]'::jsonb, array['self-esteem', 'cheerleading statements', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('strength-spotting-secret-admirer-notes-game', 'Strength Spotting Secret Admirer Notes Game', 'game'::resource_kind, 'Members write anonymous notes naming a specific strength they saw in others during group, delivered at the end and read aloud.', 'Use it to let a group practice noticing strengths in others and receiving them without deflecting.', array['Groups', 'Teens']::text[], '15 minutes at the end of a session', 'Rules: at the start of session each member is told to watch for strengths in others during the group. In the last fifteen minutes everyone writes one anonymous note for at least two other members, naming a specific moment and the strength it showed: when you asked Sam if he was okay, that was attentiveness. The leader deals the notes out, and each receiver reads theirs aloud without comment or deflection, just thank you. Debrief: what it was like to read yours aloud, whether anything surprised them, and what they do with a compliment normally. Watch for vague notes.', '[{"id": "f0", "type": "textarea", "label": "The notes I received, copied here:"}, {"id": "f1", "type": "textarea", "label": "The one that surprised me most, and why:"}, {"id": "f2", "type": "textarea", "label": "What it was like to read them aloud and only say thank you:"}, {"id": "f3", "type": "textarea", "label": "Strengths I spotted in others today, and whether writing them was easy or hard:"}, {"id": "f4", "type": "textarea", "label": "What I normally do with a compliment, and what I did today:"}, {"id": "f5", "type": "textarea", "label": "A strength from my notes I could lean on this week:"}]'::jsonb, array['self-esteem', 'game', 'strengths', 'group']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('dog-park-chat-steps-sheet', 'Dog Park Chat Steps Sheet', 'worksheet'::resource_kind, 'A graded step sheet for talking to other owners at the dog park, from standing near the group to asking a dog''s name to a five-minute chat.', 'Use it to give a client a low-pressure social setting with a built-in topic and a ladder of steps to climb.', array['Adults', 'Teens']::text[], 'Three visits a week for a month', 'The dog park is a rare social setting where the topic is handed to you and leaving is always allowed. The sheet builds a ladder: stand within earshot of the regulars, make eye contact and nod, ask one dog''s name, answer a question about your own dog, stay for a five-minute conversation, and finally start one. Each step gets predicted anxiety, actual anxiety and what happened. The client decides when to move up. No dog is needed if a friend''s can be borrowed. Watch for a client who uses the dog as a shield for the whole month; by the top of the ladder the conversation should drift off dogs.', '[{"id": "f0", "type": "textarea", "label": "My ladder from bottom to top, in my own words, at least five steps:"}, {"id": "f1", "type": "textarea", "label": "For each step: predicted anxiety, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "For each step done: actual anxiety at the start and after two minutes, and what happened:"}, {"id": "f3", "type": "textarea", "label": "The question I will ask about someone''s dog, and the answer I will give about mine:"}, {"id": "f4", "type": "textarea", "label": "When the conversation drifted off dogs, and where it went:"}, {"id": "f5", "type": "textarea", "label": "Where else in my week a built-in topic could be found:"}]'::jsonb, array['social anxiety', 'exposure', 'hierarchy', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('asking-the-pharmacist-a-question-prediction-sheet', 'Asking the Pharmacist a Question Prediction Sheet', 'cbt'::resource_kind, 'An experiment that predicts how a pharmacist will react to a simple question at the counter, then records what actually happened.', 'Use it to help a client test beliefs about bothering people and looking foolish in a brief, structured interaction.', array['Adults', 'Teens']::text[], 'One errand, 10 minutes to set up', 'Asking a pharmacist a question combines several fears: holding up a line, not knowing the right words, being judged for the question. The sheet has the client choose a real, small question, predict the pharmacist''s reaction and the line''s reaction in detail with a confidence rating, and then ask. Afterward they record the actual response, tone and how long it took, and rerate. Keep the question genuine; a made-up one adds a layer of deception that distracts. Watch for a client who asks in a rush and leaves before the answer; the full response is the data.', '[{"id": "f0", "type": "textarea", "label": "The question I will ask, and why it is a real one:"}, {"id": "f1", "type": "textarea", "label": "My prediction of the pharmacist''s reaction: words, tone, face:"}, {"id": "f2", "type": "textarea", "label": "My prediction of the people in line, and how sure I am from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What actually happened: words, tone, how long it took:"}, {"id": "f4", "type": "textarea", "label": "What the people in line actually did:"}, {"id": "f5", "type": "textarea", "label": "My belief in the prediction now, and the next counter question I could ask:"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'predictions', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('name-tag-that-says-nervous-willingness-page', 'Name Tag That Says Nervous Willingness Page', 'act'::resource_kind, 'A willingness page that imagines wearing a name tag reading nervous into an event, letting the feeling show rather than hiding it.', 'Use it to help a client attend something while dropping the effort of hiding their anxiety.', array['Adults', 'Teens']::text[], '15 minutes before an event', 'Much of social anxiety is the second job: hiding the first. The page imagines wearing a name tag that says nervous into the event, so there is nothing to hide, and asks what the client would do with the hands and attention freed from hiding. They list the hiding behaviors they usually run, what the event is for, and what they will do instead of concealing. The tag is imaginary, though some clients choose to say it aloud to one person. Watch for a client who treats the page as permission to leave early; the tag goes in, not out.', '[{"id": "f0", "type": "textarea", "label": "The event, and what it is for in my life:"}, {"id": "f1", "type": "textarea", "label": "The hiding behaviors I usually run: how I hold my face, my hands, my drink, my voice:"}, {"id": "f2", "type": "textarea", "label": "What the name tag would say, and what would be different if everyone could read it:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the energy freed from hiding: who I will talk to, what I will ask:"}, {"id": "f4", "type": "textarea", "label": "If I choose to, the one person I will actually tell I am nervous:"}, {"id": "f5", "type": "textarea", "label": "After: what happened to the nervousness once I stopped hiding it:"}]'::jsonb, array['social anxiety', 'willingness', 'acceptance', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('check-the-facts-after-the-group-chat-went-quiet-card', 'Check the Facts After the Group Chat Went Quiet Card', 'dbt'::resource_kind, 'A Check the Facts card for the group chat that went silent after the client posted, walking the facts before shame decides.', 'Use it to give a client a DBT sequence for the post-message silence that reads as rejection by everyone at once.', array['Adults', 'Teens']::text[], '10 minutes', 'A group chat going quiet after a client''s message feels like a whole room turning away. The card runs Check the Facts: the emotion and its intensity, the prompting event as the exact message and the time since, interpretations with assumptions marked, what else is true about group chats at that hour, the threat and its likelihood, and whether the emotion fits. Then one action that is not deleting the message or sending a follow-up joke. Watch for a client who checks the facts and then checks the chat every minute; put the phone face down.', '[{"id": "f0", "type": "textarea", "label": "The emotion, and how intense it is from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "The message I sent, the time, and how long it has been quiet:"}, {"id": "f2", "type": "textarea", "label": "My interpretations, with assumptions marked:"}, {"id": "f3", "type": "textarea", "label": "What else is true about this chat at this hour, and what happened the last three times anyone''s message sat:"}, {"id": "f4", "type": "textarea", "label": "Does the emotion fit the facts? What intensity would?"}, {"id": "f5", "type": "textarea", "label": "One action that is not deleting or sending a follow-up, and where the phone goes:"}]'::jsonb, array['social anxiety', 'check the facts', 'core DBT', 'rumination']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('order-for-the-table-out-loud-restaurant-role-play-game', 'Order for the Table Out Loud Restaurant Role-Play Game', 'game'::resource_kind, 'Each player orders for the whole table from a menu, handling a substitution and a mistake, with a debrief on being the center of attention.', 'Use it to let a group rehearse one of the most avoided public speaking moments with laughs and repetition.', array['Groups', 'Teens']::text[], '25 minutes', 'Rules: one player is the waiter, one orders for the table, the rest are the table. The orderer gets a real menu and must order for everyone, including one substitution and one question about a dish. The waiter plays one small complication: an item is out, or they bring the wrong thing. The table reacts as real friends would. Everyone orders once. Debrief: what each person feared before their turn, what the table actually did, how the complication felt, and what they would do at a real restaurant this week. Watch for a waiter who plays rude; the complication is ordinary, not hostile.', '[{"id": "f0", "type": "textarea", "label": "What I feared before my turn to order:"}, {"id": "f1", "type": "textarea", "label": "The substitution I asked for, and how the waiter responded:"}, {"id": "f2", "type": "textarea", "label": "The complication I got, and what I did:"}, {"id": "f3", "type": "textarea", "label": "What the table actually did while I ordered:"}, {"id": "f4", "type": "textarea", "label": "What my anxiety did between the first word and the last:"}, {"id": "f5", "type": "textarea", "label": "The real restaurant moment I will take this week:"}]'::jsonb, array['social anxiety', 'game', 'exposure', 'group']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('their-recipes-cooking-day-plan-sheet', 'Their Recipes Cooking Day Plan Sheet', 'worksheet'::resource_kind, 'A plan for the day a client first cooks a dead person''s recipe: who is there, what may go wrong and what happens after the meal.', 'Use it to help a client approach a loaded ritual with a plan that leaves room for the feelings it will bring.', array['Adults', 'Teens']::text[], '20 minutes to plan, one afternoon', 'Cooking a dead person''s recipe is a doorway many clients approach and back away from for years. The sheet plans one afternoon: which recipe, whose handwriting it is in, who will be in the kitchen or on the phone, what is allowed to go wrong, how the client will handle the moment the smell arrives, and what they will do with the first hour after the meal. It also asks what the person would say about the attempt. The plan can be used again for the next recipe. Watch for a client who plans to do it alone on the anniversary; suggest an ordinary day and one person.', '[{"id": "f0", "type": "textarea", "label": "The recipe, whose hand it is written in, and when I will cook it:"}, {"id": "f1", "type": "textarea", "label": "Who will be in the kitchen or on the phone:"}, {"id": "f2", "type": "textarea", "label": "What is allowed to go wrong, and what I will do if it does:"}, {"id": "f3", "type": "textarea", "label": "What I will do in the moment the smell arrives:"}, {"id": "f4", "type": "textarea", "label": "What they would say about my attempt:"}, {"id": "f5", "type": "textarea", "label": "The first hour after the meal: what I will do, and who I will tell about it:"}]'::jsonb, array['grief and loss', 'pacing', 'planning', 'rituals']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('forgetting-their-voice-means-forgetting-them-check-sheet', 'Forgetting Their Voice Means Forgetting Them Check Sheet', 'cbt'::resource_kind, 'A sheet for the fear that no longer hearing a dead person''s voice in memory means losing them, checking what memory actually keeps.', 'Use it to help a grieving client separate the fading of a sensory memory from the loss of the person inside them.', array['Adults', 'Teens']::text[], '20 minutes in session', 'Many grieving clients reach a day when they cannot summon the voice, and panic that this is the real loss. The sheet names the thought and the fear under it, then takes inventory of what is still vivid: a gesture, a phrase, a laugh, how they entered a room. It asks what the client knows about how memory works for everyone, what they would tell a friend who said the same, and what of the person lives in how the client now moves through a day. Finish with a balanced thought. Recordings and voicemails stay out of the homework. Watch for the sheet becoming a test the client runs daily.', '[{"id": "f0", "type": "textarea", "label": "The thought, and the fear underneath it:"}, {"id": "f1", "type": "textarea", "label": "What is still vivid: a gesture, a phrase, a laugh, the way they entered a room:"}, {"id": "f2", "type": "textarea", "label": "What I know about how everyone''s memory of a voice changes over time:"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend who said they were losing their person this way:"}, {"id": "f4", "type": "textarea", "label": "What of them lives in how I move through a day now:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and how I will respond the next time I reach for the voice and miss it:"}]'::jsonb, array['grief and loss', 'thinking traps', 'core CBT', 'memory']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('loving-them-out-loud-values-page', 'Loving Them Out Loud Values Page', 'act'::resource_kind, 'A values page that turns a grieving client''s love for the person into actions that can be done this month, so the love has somewhere to go.', 'Use it to help a client whose love now has no recipient find committed actions that carry it forward.', array['Adults', 'Teens']::text[], '20 minutes', 'Grief is love with nowhere to go, and this page gives it places. The client lists what the person valued, what the client loved about them, and what they used to do together. Then they translate each into an action available this month: a cause the person cared about, a habit of theirs the client could carry, a story told to someone who never met them, a place visited. Actions are small and dated. The page is not about moving on; it is about what the love does now. Watch for a client who picks actions out of obligation; each one should feel like the person, not like a chore.', '[{"id": "f0", "type": "textarea", "label": "What they valued, and what I loved about them:"}, {"id": "f1", "type": "textarea", "label": "What we used to do together that I miss most:"}, {"id": "f2", "type": "textarea", "label": "Each of those translated into something I could do this month, however small:"}, {"id": "f3", "type": "textarea", "label": "One story about them I will tell someone who never met them, and to whom:"}, {"id": "f4", "type": "textarea", "label": "The actions I pick, with dates:"}, {"id": "f5", "type": "textarea", "label": "What it was like to do the first one, and where the love went:"}]'::jsonb, array['grief and loss', 'values', 'committed action', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-skipping-the-memorial-card', 'Opposite Action to Skipping the Memorial Card', 'dbt'::resource_kind, 'An opposite action card for the urge to skip a memorial or gathering out of dread, with the all-the-way version of showing up planned.', 'Use it to help a grieving client attend something they will regret missing, when the dread does not fit what the gathering is for.', array['Adults', 'Teens']::text[], '15 minutes before the event', 'The urge to skip a memorial is strong and the regret afterward can last years. The card first checks: does the dread fit the facts, and would skipping work for the client''s goals and values? If not, opposite action, all the way: go, arrive on time, stand near the people who matter, speak to one person, stay for a set time. The card also plans what they will do with the dread in the car and a leaving time that is a decision rather than an escape. Watch for a client who attends and spends the whole time in the parking lot; the all-the-way version includes being in the room.', '[{"id": "f0", "type": "textarea", "label": "The gathering, and the urge to skip it in my words:"}, {"id": "f1", "type": "textarea", "label": "Does the dread fit the facts? Would skipping serve what I care about?"}, {"id": "f2", "type": "textarea", "label": "Opposite action all the way: arrive when, stand where, speak to whom, stay how long:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the dread in the car on the way:"}, {"id": "f4", "type": "textarea", "label": "My leaving time, decided now, not in the moment:"}, {"id": "f5", "type": "textarea", "label": "After: what it was like to be in the room, and what I would have missed:"}]'::jsonb, array['grief and loss', 'opposite action', 'core DBT', 'avoidance']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('sad-and-happy-memory-flip-book-craft', 'Sad and Happy Memory Flip Book Craft', 'kids'::resource_kind, 'A flip book where each page holds a drawn memory of the person who died, with sad and happy pages allowed side by side.', 'Use it to help a child hold both sad and happy memories of someone who died without having to pick one feeling.', array['Children']::text[], '45 minutes, added to over weeks', 'Children often think they must be either sad or fine about a death. The flip book holds both. The child and parent cut and staple a small book, and on each page the child draws one memory of the person, labeling it with a feeling face in the corner. Sad pages and happy pages can follow each other. The parent draws a page too and talks about their own memory in a few sentences. The book stays somewhere the child can reach and add to. Watch for a parent who steers toward happy pages; the sad ones are the reason the book exists.', '[{"id": "f0", "type": "textarea", "label": "Draw the cover: the person''s name and something that was theirs:"}, {"id": "f1", "type": "textarea", "label": "A happy memory page, with its feeling face:"}, {"id": "f2", "type": "textarea", "label": "A sad memory page, with its feeling face:"}, {"id": "f3", "type": "textarea", "label": "A page I want to draw but do not know how yet:"}, {"id": "f4", "type": "textarea", "label": "Grown-up: the page I drew, and what I said about it:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: how I let a sad page be sad without rushing to the next one:"}]'::jsonb, array['grief and loss', 'children', 'craft', 'family']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('friendship-fading-out-decision-sheet', 'Friendship Fading Out Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for a friendship gone quiet, weighing a direct conversation, a renewed effort or letting it fade, with what each costs.', 'Use it to help a client make a deliberate choice about a drifting friendship instead of letting silence decide.', array['Adults', 'Teens']::text[], '20 minutes', 'Friendships end more often by fading than by fighting, and the fade leaves clients with a vague ache and no decision. The sheet names the friend, how the fade happened, what the friendship gave at its best, and what the client suspects happened. Then three options with costs: say something direct, make a renewed effort for a set time, or let it fade with intention. Whichever they pick, the sheet asks what they will actually do and by when. Watch for a client who picks the direct conversation and writes an accusation; the sheet offers a line that names the drift without blame.', '[{"id": "f0", "type": "textarea", "label": "The friend, how the fade happened, and what the friendship gave me at its best:"}, {"id": "f1", "type": "textarea", "label": "What I suspect happened, and what I actually know:"}, {"id": "f2", "type": "textarea", "label": "Option one: the direct line I could send that names the drift without blame, and what it might cost:"}, {"id": "f3", "type": "textarea", "label": "Option two: a renewed effort for a set time, what that looks like, and what it might cost:"}, {"id": "f4", "type": "textarea", "label": "Option three: letting it fade on purpose, and what that would cost:"}, {"id": "f5", "type": "textarea", "label": "My choice, what I will do, and by when:"}]'::jsonb, array['relationship issues', 'decisions', 'communication', 'friendship']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('they-changed-the-plan-to-disrespect-me-check-sheet', 'They Changed the Plan to Disrespect Me Check Sheet', 'cbt'::resource_kind, 'A sheet for the personalization that fires when someone changes a plan, checking whether the change was about the client at all.', 'Use it to help a client catch the habit of reading every schedule change as a statement about their worth.', array['Adults', 'Teens']::text[], '10 minutes when the plan changes', 'A moved dinner or a canceled call can land as a verdict: they do not respect my time, I am not a priority. The sheet records the change exactly as it was communicated, the meaning the client attached, the feeling, and then the alternative explanations rooted in the other person''s week. It asks how the client has changed plans on others and what that meant about them. Finish with a balanced thought and the reply they will send. Watch for a client with a real pattern of being bumped by one person; the sheet counts, and a count is evidence for a different conversation.', '[{"id": "f0", "type": "textarea", "label": "The change, exactly as it was communicated to me:"}, {"id": "f1", "type": "textarea", "label": "What I decided it meant about me, and the feeling from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "Four things that could be going on in their week that would explain it:"}, {"id": "f3", "type": "textarea", "label": "Times I have changed a plan on someone, and what it meant about them:"}, {"id": "f4", "type": "textarea", "label": "How many times this person has changed plans in the last few months, honestly counted:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and the reply I will actually send:"}]'::jsonb, array['relationship issues', 'thinking traps', 'personalization', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('old-argument-rerun-channel-change-page', 'Old Argument Rerun Channel Change Page', 'act'::resource_kind, 'A defusion page for the argument the mind keeps replaying, treating the replay as a rerun the client can notice and change the channel on.', 'Use it to help a client stop rehearsing a settled or unwinnable argument and return attention to the relationship as it is today.', array['Adults', 'Teens']::text[], '15 minutes', 'Some arguments are over and still playing. The page has the client describe the rerun: who it is with, the episode that repeats, the lines they deliver better each time, and how often it airs. Then the practice: notice the rerun has started, name it, here is the kitchen fight again, and change the channel to something in the present with their hands. The rerun will come back on; the practice is the changing, not the canceling. Finish with what the client wants with that person now, apart from winning. Watch for a client who uses the page to script the next real argument.', '[{"id": "f0", "type": "textarea", "label": "The rerun: who it is with, the episode that repeats, and how often it airs:"}, {"id": "f1", "type": "textarea", "label": "The lines I deliver better every time it plays:"}, {"id": "f2", "type": "textarea", "label": "What watching the rerun has gotten me, and what it costs:"}, {"id": "f3", "type": "textarea", "label": "My line for noticing it, and what my hands will do when I change the channel:"}, {"id": "f4", "type": "textarea", "label": "How many times this week I changed the channel, roughly:"}, {"id": "f5", "type": "textarea", "label": "What I want with this person now, apart from winning:"}]'::jsonb, array['relationship issues', 'defusion', 'rumination', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('dear-man-for-the-roommates-dishes-card', 'DEAR MAN for the Roommate''s Dishes Card', 'dbt'::resource_kind, 'A DEAR MAN card for the roommate who leaves dishes in the sink, with each letter scripted for one conversation and a plan for the pushback.', 'Use it to give a client a complete interpersonal effectiveness script for a small, recurring household request.', array['Adults', 'Teens']::text[], '15 minutes to write, one conversation', 'The dishes are the training ground for asking for things. The card scripts DEAR MAN for one conversation: Describe the sink without adjectives, Express the feeling in one sentence, Assert the specific request, Reinforce what the roommate gets, stay Mindful when the subject changes, Appear confident with posture and voice, Negotiate an alternative they can live with. The client writes each line, rehearses aloud in session, picks a time when no one is tired, and reports back. Watch for Describe lines that contain always or never; the sink is described as it was this morning.', '[{"id": "f0", "type": "textarea", "label": "Describe: the sink this morning, in facts only:"}, {"id": "f1", "type": "textarea", "label": "Express: how I feel about it, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "Assert: the specific request, and Reinforce: what they get if it happens:"}, {"id": "f3", "type": "textarea", "label": "Mindful: what I will say when the subject changes or they bring up my habits:"}, {"id": "f4", "type": "textarea", "label": "Appear confident: what my voice and posture will do:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: an alternative I could live with, and when I will have the conversation:"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('separate-hobbies-time-agreement-for-partners', 'Separate Hobbies Time Agreement for Partners', 'couples'::resource_kind, 'An agreement protecting time for each partner''s own hobby, with both naming what they need alone and what they fear about the other''s time.', 'Use it to help a couple protect individual time without it reading as rejection or escape.', array['Couples']::text[], '20 minutes', 'One partner''s hobby is often the other partner''s evidence of being left. The agreement has each partner write what their own activity gives them, how much time would be enough, and what they feel when the other disappears into theirs. Then the schedule: which evenings or hours are protected for each, what is not allowed to interrupt them, and the small reconnection afterward, ten minutes of showing what they made or did. Both partners get time, even if one has to find a hobby. Watch for a schedule that gives one partner three evenings and the other none; equal is the starting point.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what my activity gives me, how much time would be enough, and what I feel when you are in yours:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what my activity gives me, how much time would be enough, and what I feel when you are in yours:"}, {"id": "f2", "type": "textarea", "label": "The protected hours for each of us this week, written down:"}, {"id": "f3", "type": "textarea", "label": "What is not allowed to interrupt protected time, and what is:"}, {"id": "f4", "type": "textarea", "label": "Our ten-minute reconnection afterward: what we show or tell each other:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what the time gave each of us, and what still feels unfair:"}]'::jsonb, array['relationship issues', 'couples', 'boundaries', 'needs']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('unexpected-hug-from-a-relative-plan-sheet', 'Unexpected Hug From a Relative Plan Sheet', 'worksheet'::resource_kind, 'A plan for the gathering where relatives hug without asking, with a greeting offered first, a declining sentence and an ally who knows.', 'Use it to help a survivor go to a family event with a plan for unwanted touch that keeps them in charge of their body.', array['Adults', 'Teens']::text[], '15 minutes before the gathering', 'For a survivor, the uncle who hugs everyone and the aunt who grabs faces are not small things. The sheet stays practical: who tends to touch without asking, the client''s preferred greeting, a hand out first, a wave, a step back with a smile, a sentence that declines without explaining, and the one person at the gathering who knows and can step in. It also plans a spot to take five minutes alone and a ride home that does not depend on anyone. Watch for a client who plans to endure the hugs to keep the peace; name that their body is theirs at the party too.', '[{"id": "f0", "type": "textarea", "label": "Who at this gathering tends to touch without asking:"}, {"id": "f1", "type": "textarea", "label": "My preferred greeting, and how I will offer it first:"}, {"id": "f2", "type": "textarea", "label": "The sentence I will use to decline a hug without explaining:"}, {"id": "f3", "type": "textarea", "label": "The one person there who knows, and what I have asked them to do:"}, {"id": "f4", "type": "textarea", "label": "The spot where I can take five minutes alone, and my ride home that does not depend on anyone:"}, {"id": "f5", "type": "textarea", "label": "After: what happened, what held, and what I would change:"}]'::jsonb, array['sexual abuse', 'safety', 'boundaries', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('setting-a-boundary-will-cause-a-scene-prediction-sheet', 'Setting a Boundary Will Cause a Scene Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the belief that saying no to something small will cause a scene, tested on one boundary with a safe person.', 'Use it to help a client test the prediction that boundaries bring catastrophe, starting with a boundary that costs little.', array['Adults', 'Teens']::text[], '15 minutes to set up, one boundary', 'Many survivors learned that saying no had consequences, and the lesson generalizes to every no. The sheet picks a small boundary with a safe person, declining a second helping, ending a call at a set time, asking a friend not to drop by unannounced, and predicts the scene in detail: words, faces, what happens after. Then the client sets the boundary and records what actually happened. The person is chosen for safety, never for difficulty. Watch for a client who picks a boundary with an unsafe person to prove the point; redirect to the safe one.', '[{"id": "f0", "type": "textarea", "label": "The small boundary, and the safe person I will set it with:"}, {"id": "f1", "type": "textarea", "label": "The scene I predict: their words, their face, and what happens after:"}, {"id": "f2", "type": "textarea", "label": "How sure I am, from 0 to 100, that a scene will follow:"}, {"id": "f3", "type": "textarea", "label": "What I actually said, word for word:"}, {"id": "f4", "type": "textarea", "label": "What actually happened: words, face, after:"}, {"id": "f5", "type": "textarea", "label": "My belief now, and the next small boundary with a safe person:"}]'::jsonb, array['sexual abuse', 'predictions', 'boundaries', 'behavioral experiment']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('choosing-who-gets-a-seat-at-my-table-values-page', 'Choosing Who Gets a Seat at My Table Values Page', 'act'::resource_kind, 'A values page picturing life as a table the client sets, choosing who gets a seat, who gets a visit and who stays outside.', 'Use it to help a survivor practice authorship over who is close, as a present-tense choice rather than a reaction.', array['Adults', 'Teens']::text[], '20 minutes', 'Survivors often describe closeness as something that happens to them. The page makes it something they set. The client draws or lists a table with a number of seats they choose, names the values a person at the table would need to show, and places people: at the table, at the door for visits, or outside. Nobody has to be placed who is not safe to think about, and the past is not discussed. The page ends with one person who deserves more of a seat and one small invitation. Watch for a client who fills every seat out of obligation; an empty seat is allowed.', '[{"id": "f0", "type": "textarea", "label": "My table: how many seats I want, and what a person needs to show to sit there:"}, {"id": "f1", "type": "textarea", "label": "Who sits at the table today:"}, {"id": "f2", "type": "textarea", "label": "Who gets a visit at the door, and who stays outside, without explanation owed:"}, {"id": "f3", "type": "textarea", "label": "The person who deserves more of a seat than they have:"}, {"id": "f4", "type": "textarea", "label": "One small invitation I could offer them this month:"}, {"id": "f5", "type": "textarea", "label": "What it is like to be the one who sets the table:"}]'::jsonb, array['sexual abuse', 'values', 'boundaries', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-isolating-after-a-trigger-card', 'Opposite Action to Isolating After a Trigger Card', 'dbt'::resource_kind, 'An opposite action card for the pull to disappear after a trigger, with the smallest contact that counts and who has agreed to receive it.', 'Use it to help a survivor stay connected through the days after a trigger when shame says to vanish.', array['Adults', 'Teens']::text[], 'Five minutes to plan, used in the days after', 'Shame''s urge is to disappear, and days alone after a trigger tend to deepen the hole. The card checks whether isolating fits the facts and would work, then plans the opposite action: the smallest contact that counts, a text that says rough day, no need to reply, a walk with someone who will not ask questions, sitting in a coffee shop. Two or three people are named who have agreed in advance to receive that text and know what to do with it. The card never asks about the trigger''s content. Watch for a plan that depends on the client explaining; the text needs no explanation.', '[{"id": "f0", "type": "textarea", "label": "How the pull to disappear shows up after a trigger, and how long it usually lasts:"}, {"id": "f1", "type": "textarea", "label": "Does hiding fit the facts? What does it get me, and what does it cost by day three?"}, {"id": "f2", "type": "textarea", "label": "The smallest contact that counts, written as the text I would send:"}, {"id": "f3", "type": "textarea", "label": "The two or three people who have agreed to receive it, and what they will do:"}, {"id": "f4", "type": "textarea", "label": "Where I can be around people without having to talk:"}, {"id": "f5", "type": "textarea", "label": "The next time: what I did, and what the days after looked like:"}]'::jsonb, array['sexual abuse', 'opposite action', 'support', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('tell-a-grown-up-until-someone-listens-chain-craft', 'Tell a Grown-Up Until Someone Listens Chain Craft', 'kids'::resource_kind, 'A paper chain of trusted grown-ups a child could tell if something felt wrong, with the rule to keep telling until someone listens.', 'Use it to teach a child that telling is a chain, not a single try, and give them the names in order.', array['Children']::text[], '30 minutes', 'Children who tell once and are not heard often stop. Child and parent cut paper strips, and on each the child writes or draws a grown-up they could tell if something felt wrong or someone broke a body rule: a parent, a teacher, a grandparent, a coach, a school nurse. They link them in the order the child would try, and the parent writes the rule on the first link: if one grown-up does not listen, tell the next one, and keep going. Watch for a chain that is all family; include someone at school. If a child discloses abuse during this craft, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The grown-ups on my chain, in the order I would tell them:"}, {"id": "f1", "type": "textarea", "label": "Draw the first link with the rule: keep telling until someone listens:"}, {"id": "f2", "type": "textarea", "label": "What I would say to the first grown-up, in a few words:"}, {"id": "f3", "type": "textarea", "label": "What I do if that grown-up is busy or does not understand:"}, {"id": "f4", "type": "textarea", "label": "Grown-up: how I practiced being told something small this week and listening all the way:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: the people on the chain who are not family, and whether my child knows how to reach them:"}]'::jsonb, array['sexual abuse', 'children', 'safety', 'craft']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('skills-that-need-no-supplies-pocket-list-sheet', 'Skills That Need No Supplies Pocket List Sheet', 'worksheet'::resource_kind, 'A pocket list of coping skills that need nothing but the client''s body and attention, for a bathroom stall, a car or a meeting.', 'Use it to help a client build a set of skills that work when the kit, the app and the quiet room are not available.', array['Adults', 'Teens']::text[], '15 minutes to build, carried daily', 'Many coping plans assume a quiet room and a kit. Most hard moments happen in a car, a stall or a meeting. The sheet builds a list of skills that need nothing: pressing feet into the floor, naming five things in view, long exhale, tensing and releasing hands, counting backward by sevens, a phrase said inside. The client tests each one in session, rates how well it worked, and copies the top five onto a card for a wallet or phone case. Watch for a list that includes anything requiring privacy; every item should work in a crowded elevator.', '[{"id": "f0", "type": "textarea", "label": "Every skill I can think of that needs nothing but my body and attention:"}, {"id": "f1", "type": "textarea", "label": "Tested in session: how each one worked, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "My top five, in the order I would try them:"}, {"id": "f3", "type": "textarea", "label": "The places this week where a kit or a quiet room would not have been available:"}, {"id": "f4", "type": "textarea", "label": "Which skill I used in one of those places, and what happened:"}, {"id": "f5", "type": "textarea", "label": "What I will write on the card, and where the card lives:"}]'::jsonb, array['coping skills', 'skills', 'planning', 'grounding']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('if-i-feel-better-i-was-never-really-struggling-check-sheet', 'If I Feel Better I Was Never Really Struggling Check Sheet', 'cbt'::resource_kind, 'A sheet for the thought that a skill working proves the problem was never real, checking what it leaves out and what it does to skill use.', 'Use it to help a client catch the thinking trap that punishes them for feeling better and keeps skills from sticking.', array['Adults', 'Teens']::text[], '15 minutes', 'A surprising number of clients feel worse after a skill works, because the relief seems to prove they were faking. The sheet names the thought, the feeling it produces, and the rule underneath, usually that real pain cannot be eased. It asks whether a painkiller working means a headache was fake, what a friend who felt better would deserve, and what the thought does to the next time they reach for a skill. Then a balanced thought about what a skill working actually means. Watch for a client who agrees on paper and still stops using skills; return to the sheet with the next example.', '[{"id": "f0", "type": "textarea", "label": "The thought, and when it showed up after a skill worked:"}, {"id": "f1", "type": "textarea", "label": "The feeling it produced, and the rule underneath it:"}, {"id": "f2", "type": "textarea", "label": "If a painkiller works, was the headache fake? What is different here, if anything?"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend who felt better and then doubted their own pain:"}, {"id": "f4", "type": "textarea", "label": "What this thought does to my willingness to use the skill next time:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought about what a skill working actually means:"}]'::jsonb, array['coping skills', 'thinking traps', 'core CBT', 'self-criticism']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('coping-skill-as-a-raincoat-not-a-roof-page', 'Coping Skill as a Raincoat Not a Roof Page', 'act'::resource_kind, 'A metaphor page framing a coping skill as a raincoat for walking through weather rather than a roof that keeps the weather out.', 'Use it to help a client stop judging skills by whether the feeling went away and start judging them by whether they kept moving.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients often abandon a skill because the feeling did not stop. The page offers a different measure. A raincoat does not stop the rain; it lets you walk to where you are going. The client lists skills they have dropped and what they expected each to do, then rewrites the expectation: what the skill lets them do while the feeling is still there. They pick one skill to wear as a raincoat this week on a walk they value, rain or not, and report what they got to. Watch for a client who still rates the week by how much it rained; the question is where they walked.', '[{"id": "f0", "type": "textarea", "label": "Skills I have dropped, and what I expected each to do to the feeling:"}, {"id": "f1", "type": "textarea", "label": "The same skills, rewritten: what each lets me do while the feeling is still there:"}, {"id": "f2", "type": "textarea", "label": "The walk I value this week that the weather usually stops:"}, {"id": "f3", "type": "textarea", "label": "The skill I will wear as a raincoat on that walk:"}, {"id": "f4", "type": "textarea", "label": "What the weather did, and where I got to anyway:"}, {"id": "f5", "type": "textarea", "label": "What changes if I judge a skill by where I walked instead of by the rain:"}]'::jsonb, array['coping skills', 'metaphor', 'willingness', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('distract-with-accepts-in-the-waiting-room-card', 'Distract With ACCEPTS in the Waiting Room Card', 'dbt'::resource_kind, 'An ACCEPTS card planned for a specific waiting room, with one distraction chosen for each letter and tested in the chair.', 'Use it to give a client a concrete distress tolerance plan for the wait that tends to undo them.', array['Adults', 'Teens']::text[], '10 minutes to plan, one appointment', 'Waiting rooms are where distress has nothing to do. The card plans ACCEPTS for one specific appointment: an Activity on the phone that is not a search, a Contribution such as holding a door or a kind word to the desk, a Comparison to a harder wait they survived, an Emotion to invite with a song or a photo, Pushing away the worry into an envelope for after, Thoughts that occupy the mind like counting tiles, and a Sensation such as a cold drink. One per letter, rated afterward. Watch for a client who chooses searching their symptoms as the activity; that is the thing the card is for.', '[{"id": "f0", "type": "textarea", "label": "The appointment, and how long I usually wait:"}, {"id": "f1", "type": "textarea", "label": "One distraction for each letter: Activities, Contributing, Comparisons, Emotions, Pushing away, Thoughts, Sensations:"}, {"id": "f2", "type": "textarea", "label": "The order I will try them in the chair:"}, {"id": "f3", "type": "textarea", "label": "My distress at the start of the wait and when my name was called, 0 to 100:"}, {"id": "f4", "type": "textarea", "label": "Which letters worked in that chair, and which did not:"}, {"id": "f5", "type": "textarea", "label": "The card for my next appointment, revised:"}]'::jsonb, array['coping skills', 'ACCEPTS', 'distress tolerance', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('coping-skill-mad-libs-fill-in-game', 'Coping Skill Mad Libs Fill-In Game', 'game'::resource_kind, 'Players supply skills, feelings and places to a blank-filled story, read the ridiculous result aloud, then fix it into a plan that fits.', 'Use it to get a group laughing while they practice matching skills to situations and seeing why mismatches fail.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Rules: the leader has a short template story with blanks: a feeling, a place, a body sign, a coping skill, a person, a time. Without hearing the story, players call out words for each blank in turn. The leader reads the finished story aloud: when I felt furious in the dentist chair my ears went hot so I did jumping jacks and called my grandmother. The group laughs, then the real round: fix the story with a skill that would actually fit that place and feeling, and say why the first one failed. Three or four stories. Debrief: which mismatches were funny because they were true to life.', '[{"id": "f0", "type": "textarea", "label": "The silliest story we made, and the skill that did not fit the place:"}, {"id": "f1", "type": "textarea", "label": "How we fixed it: the skill that would work there, and why:"}, {"id": "f2", "type": "textarea", "label": "A mismatch from the game that I have actually tried in real life:"}, {"id": "f3", "type": "textarea", "label": "A place in my week where my usual skill does not fit, and a better one:"}, {"id": "f4", "type": "textarea", "label": "The feeling and place I would put in my own template story:"}, {"id": "f5", "type": "textarea", "label": "One skill I heard today that I had not thought of as a skill:"}]'::jsonb, array['coping skills', 'game', 'skills', 'group']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('thunderstorm-watch-from-the-porch-step-plan-sheet', 'Thunderstorm Watch From the Porch Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for a client who hides from storms, moving from a closed room to a window to the porch over several storms.', 'Use it to give a client a graded approach to storms that uses the weather itself as the schedule.', array['Adults', 'Teens', 'Children']::text[], 'Several storms over a season', 'Storm fear is awkward to practice because the storms choose the time. The sheet makes a ladder to use whenever one arrives: an interior room with the sound on, a room with a window and the blinds open, standing at the window, the open doorway, the covered porch, and finally the porch for the whole storm. Each storm gets one step, with predicted and actual fear, what the client noticed about the sound and the light, and how long until the fear eased. A trusted person can be present early and not late. Watch for a client who moves up only on mild storms; a loud one at a lower step counts too.', '[{"id": "f0", "type": "textarea", "label": "My ladder from the inside room to the porch, in my own words:"}, {"id": "f1", "type": "textarea", "label": "The step I will take at the next storm, and who will be with me:"}, {"id": "f2", "type": "textarea", "label": "Predicted fear, 0 to 100, and actual fear at the start and after ten minutes:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the sound, the light and my body:"}, {"id": "f4", "type": "textarea", "label": "How long the fear took to ease, and what I did while waiting:"}, {"id": "f5", "type": "textarea", "label": "The step for the storm after this one:"}]'::jsonb, array['phobias', 'exposure', 'hierarchy', 'planning']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('deep-end-of-the-pool-prediction-sheet', 'Deep End of the Pool Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for fear of deep water, forecasting what will happen at each distance from the shallow end and recording what did.', 'Use it to help a client test fear predictions about deep water in a pool with a lifeguard and a clear edge.', array['Adults', 'Teens']::text[], 'Three or four pool visits', 'Deep water fear has clear predictions: I will sink, I will panic and swallow water, I will not be able to get back. A pool with a lifeguard and a visible edge is a good place to test them. The sheet marks distances along the pool edge and for each has the client predict what will happen and how sure they are, then enter to that point holding the edge and record the result. Being able to float or hold the wall is the data. Progress happens across visits, not in one. Watch for a client who tests with a flotation device every time; by the third visit the device stays on the deck.', '[{"id": "f0", "type": "textarea", "label": "My predictions for deep water, in exact words:"}, {"id": "f1", "type": "textarea", "label": "The pool, the lifeguard hours, and the markers I will use along the edge:"}, {"id": "f2", "type": "textarea", "label": "For each marker: what I predict, how sure I am, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "For each marker reached: what actually happened, including what my body did:"}, {"id": "f4", "type": "textarea", "label": "What held me up when I let go of the edge for a count of three:"}, {"id": "f5", "type": "textarea", "label": "My belief in the original predictions now, and the marker for next visit:"}]'::jsonb, array['phobias', 'predictions', 'exposure', 'core CBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('letting-fear-hold-the-handrail-with-me-page', 'Letting Fear Hold the Handrail With Me Page', 'act'::resource_kind, 'A willingness page for a feared physical task where fear is invited to hold the handrail alongside the client rather than be shaken off.', 'Use it to help a client approach a feared place with fear present and their hands and feet still doing the task.', array['Adults', 'Teens']::text[], '15 minutes before an approach', 'Clients often wait to feel calm before the first step, and the step never comes. This page invites fear to come along and hold the rail. The client names the feared task, describes what fear will feel like in the body on the first step, and writes what their hands and feet will do regardless: hand on the rail, one step, breathe out, next step. Fear gets a name and a place, next to them rather than in the way. Afterward, what fear did on the way up. Watch for a client who grips the rail to control the fear; the rail is for the body, and fear is allowed to grip too.', '[{"id": "f0", "type": "textarea", "label": "The feared task, and where exactly it begins:"}, {"id": "f1", "type": "textarea", "label": "What fear will feel like in my body on the first step:"}, {"id": "f2", "type": "textarea", "label": "What my hands and feet will do regardless, step by step:"}, {"id": "f3", "type": "textarea", "label": "Fear''s name, and where it stands or holds on while I move:"}, {"id": "f4", "type": "textarea", "label": "What fear did between the first step and the last:"}, {"id": "f5", "type": "textarea", "label": "The next place I could let fear hold the rail with me:"}]'::jsonb, array['phobias', 'willingness', 'exposure', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('paced-breathing-before-the-mri-card', 'Paced Breathing Before the MRI Card', 'dbt'::resource_kind, 'A paced breathing card for the minutes before and inside an MRI, rehearsed at home, with a cue to start and a plan for the noise.', 'Use it to give a client one rehearsed breathing rhythm for a scan they have been avoiding or dreading.', array['Adults', 'Teens']::text[], 'Five minutes a day for the week before', 'An MRI combines enclosure, noise and stillness, and clients who have canceled one often have no plan beyond hoping. The card rehearses paced breathing at home for a week: an inhale count, a longer exhale count, and a pace of about five or six breaths a minute, practiced lying down with eyes closed to mimic the scan. It plans the cue to start in the waiting room, what to count when the machine knocks, and the sentence to say to the technician before going in. The scan is the practice, not the test. Watch for a client who breathes fast and deep; slow and ordinary is the point.', '[{"id": "f0", "type": "textarea", "label": "My inhale and exhale counts, and how they felt lying down with eyes closed:"}, {"id": "f1", "type": "textarea", "label": "Practice this week: when I did it, and how my body felt after five minutes:"}, {"id": "f2", "type": "textarea", "label": "The cue to start in the waiting room:"}, {"id": "f3", "type": "textarea", "label": "What I will count or say when the machine gets loud:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will say to the technician before I go in:"}, {"id": "f5", "type": "textarea", "label": "After the scan: what the breathing did, and what I would tell someone else before theirs:"}]'::jsonb, array['phobias', 'breathing', 'distress tolerance', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('brave-steps-dice-roll-approach-game', 'Brave Steps Dice Roll Approach Game', 'game'::resource_kind, 'Players roll a die to choose how many steps to take toward a feared but safe object, with a brave card at each stop and a debrief.', 'Use it to turn an approach to a feared object into a game of chance that keeps the child moving and the adult cheering.', array['Children', 'Groups']::text[], '20 minutes', 'Rules: the feared but safe object, a toy spider, a picture of a dog, a balloon, sits at one end of the room. Players start at the other end. On each turn a player rolls a die and takes that many steps toward the object, then draws a brave card with a small task: say hello to it, describe its color, take a photo, touch it with a finger. A player can pass once per game. Debrief: what the fear said at each stop, what actually happened at touch, and how the fear number changed. Watch for an adult who shortens the steps to speed it up; the die decides.', '[{"id": "f0", "type": "textarea", "label": "The object, and my fear number before the first roll, 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "My rolls, and the brave card I drew at each stop:"}, {"id": "f2", "type": "textarea", "label": "What the fear said at the middle of the room:"}, {"id": "f3", "type": "textarea", "label": "What happened when I touched it or got closest:"}, {"id": "f4", "type": "textarea", "label": "My fear number after the last roll:"}, {"id": "f5", "type": "textarea", "label": "Grown-up: how I let the die decide and cheered every roll, even the ones:"}]'::jsonb, array['phobias', 'game', 'exposure', 'children']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('getting-dressed-time-and-outfit-changes-log', 'Getting Dressed Time and Outfit Changes Log', 'worksheet'::resource_kind, 'A log of how long getting dressed takes and how many outfit changes happen, with the thought behind each change and a limit to try.', 'Use it to help a client see how body distress shapes their mornings and try one small change to the routine.', array['Adults', 'Teens']::text[], 'Five days, two minutes a morning', 'For some clients getting dressed is a daily ordeal of changes, mirror checks and lateness. The log captures five mornings: minutes from closet to door, number of changes, the thought before each change, and the mood walking out. It never asks about the body itself, only about the time and the thoughts. After five days the client picks a limit, two outfits or ten minutes, and tries it for a week. Review what the mornings cost and what the limit did. Watch for a client who meets the limit by wearing the same baggy thing daily; that is avoidance wearing a plan.', '[{"id": "f0", "type": "textarea", "label": "Each morning: minutes from closet to door, and number of outfit changes:"}, {"id": "f1", "type": "textarea", "label": "The thought before each change, in the words my mind used:"}, {"id": "f2", "type": "textarea", "label": "My mood walking out the door, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What the mornings cost me this week: time, lateness, energy:"}, {"id": "f4", "type": "textarea", "label": "The limit I will try: outfits or minutes, and what I will do when the urge to change hits it:"}, {"id": "f5", "type": "textarea", "label": "After a week with the limit: what happened to the mornings and the moods:"}]'::jsonb, array['body image', 'self-monitoring', 'routines', 'avoidance']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('if-i-looked-different-my-life-would-work-belief-sheet', 'If I Looked Different My Life Would Work Belief Sheet', 'cbt'::resource_kind, 'A sheet for the belief that a different body would fix the client''s life, checking the specific problems against what actually drives them.', 'Use it to help a client separate the problems they have from the body they blame for them.', array['Adults', 'Teens']::text[], '20 minutes in session', 'If I looked different, I would have the job, the partner, the confidence. The sheet lists the specific things the client believes would be different, then asks for each: what actually drives that outcome, who they know who has it with a body unlike the ideal, and what would still need doing if their appearance changed tomorrow. It never discusses the body itself. The point is to return the problems to where they can be worked on. Watch for a client who answers that appearance drives everything; ask about one person they admire whose life works without the ideal.', '[{"id": "f0", "type": "textarea", "label": "The belief, and the specific things that would be different if I looked different:"}, {"id": "f1", "type": "textarea", "label": "For each thing: what actually tends to drive it, as far as I can tell:"}, {"id": "f2", "type": "textarea", "label": "People I know who have each of those things with bodies unlike the ideal:"}, {"id": "f3", "type": "textarea", "label": "What would still need doing if my appearance changed overnight:"}, {"id": "f4", "type": "textarea", "label": "A more accurate thought about where these problems live:"}, {"id": "f5", "type": "textarea", "label": "One of those problems I can work on this month without changing anything about how I look:"}]'::jsonb, array['body image', 'core beliefs', 'core CBT', 'thinking traps']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('the-body-critic-on-mute-not-deleted-page', 'The Body Critic on Mute Not Deleted Page', 'act'::resource_kind, 'A defusion page that treats the body critic as a voice on mute, present but not amplified, so the client can get on with the day.', 'Use it to help a client stop fighting the appearance critic and practice letting it run quietly while they get on with their day.', array['Adults', 'Teens']::text[], '15 minutes', 'The body critic will not be deleted, and fighting it turns the volume up. The page asks the client to write a typical minute of the critic''s commentary, notice what they do to silence it, and then practice the mute: letting the critic keep talking while the client''s attention goes to the task, the conversation, the walk. Mute does not mean agreeing or arguing. The client logs moments this week when they noticed the critic and left it on mute. Nothing on the page describes the body. Watch for a client who checks a mirror to prove the critic wrong; checking is unmuting.', '[{"id": "f0", "type": "textarea", "label": "A typical minute of the critic''s commentary, written as it speaks:"}, {"id": "f1", "type": "textarea", "label": "What I usually do to silence it, and what that does to the volume:"}, {"id": "f2", "type": "textarea", "label": "What mute would look like: the critic talking while my attention goes where?"}, {"id": "f3", "type": "textarea", "label": "Moments this week I noticed the critic and left it on mute:"}, {"id": "f4", "type": "textarea", "label": "What my attention got to do instead:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the critic''s volume once I stopped reaching for the remote:"}]'::jsonb, array['body image', 'defusion', 'self-criticism', 'core ACT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-skipping-the-pool-party-card', 'Opposite Action to Skipping the Pool Party Card', 'dbt'::resource_kind, 'An opposite action card for the urge to skip a pool party over body shame, with the all-the-way version planned from the suit to the swim.', 'Use it to help a client attend the event shame is canceling, when the shame does not fit the facts of who will be there.', array['Adults', 'Teens']::text[], '15 minutes before the event', 'Shame says stay home, and each stayed-home summer makes the next harder. The card checks whether the shame fits the facts: who will be there, what they are there for, whether anyone has ever said the thing shame predicts. If it does not fit, opposite action all the way: go, wear the suit, sit in the sun, get in the water within the first half hour, talk to people with the face up. The card plans what to do with the shame in the car and the first ten minutes. Watch for a client who goes and stays wrapped in a towel the whole time; the water is the all-the-way version.', '[{"id": "f0", "type": "textarea", "label": "The event, who will be there, and what they are there for:"}, {"id": "f1", "type": "textarea", "label": "What shame predicts will happen, and whether anyone has ever actually done that:"}, {"id": "f2", "type": "textarea", "label": "Does the shame fit the facts? Would skipping serve what I care about?"}, {"id": "f3", "type": "textarea", "label": "Opposite action all the way: what I wear, where I sit, when I get in the water:"}, {"id": "f4", "type": "textarea", "label": "What I do with the shame in the car and the first ten minutes:"}, {"id": "f5", "type": "textarea", "label": "After: what people actually did, and what the water was like:"}]'::jsonb, array['body image', 'opposite action', 'avoidance', 'core DBT']::text[], '2026-11-19T15:00:00+00:00'::timestamptz),
  ('mirror-comment-moratorium-agreement-for-partners', 'Mirror Comment Moratorium Agreement for Partners', 'couples'::resource_kind, 'An agreement for partners to stop commenting on their own bodies in front of each other for a month, noting how the talk lands.', 'Use it to help a couple notice how their own body talk lands on each other and try a month without it.', array['Couples']::text[], '20 minutes to set up, one month', 'Partners often police each other''s body talk while narrating their own: I look terrible today, I cannot wear this. The agreement has each partner write the comments they make about their own body in front of the other, what they want when they say them, and what they feel when they hear the other''s. Then a one-month moratorium on body commentary about oneself, with a replacement sentence for the mirror moment, and what the other partner says instead of reassurance. Watch for a partner who uses the agreement to catch the other; the tally is each partner''s own.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the things I say about my own body in front of you, and what I want when I say them:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I feel when I hear you comment on yours:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the things I say about my own body in front of you, and what I want when I say them:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I feel when I hear you comment on yours:"}, {"id": "f4", "type": "textarea", "label": "Our month without body commentary: the replacement sentence for the mirror moment, and what the other says instead:"}, {"id": "f5", "type": "textarea", "label": "After a month: what changed in the bathroom and the bedroom, and what each of us missed or did not:"}]'::jsonb, array['body image', 'couples', 'boundaries', 'self-talk']::text[], '2026-11-19T15:00:00+00:00'::timestamptz)
